// 書き下しと読み（江﨑孔一提供の易経資料 xlsx「六十四卦」シートより）
(function(){var X={"1": {"k": "乾は元亨利貞。（乾は元に亨る貞しきに利ろし。）", "rk": "けん げん こう り てい けん おおい とお ただ よ", "t": "大なるかな乾元、萬物資りて始まる。乃ち天を統ぶ。雲行き雨施し、品物、形を流く。大明終始し、六位時に成り、時に六龍に乘りて以て天を御す。乾道變化し、各々性命を正しくし、大和を保合す。乃ち利貞なり。首として庶物に出で、萬國咸く寧し。", "rt": "だい けんげん ばんぶつ と はじ すなわ てん す くも ゆ あめほどこ ひんぶつ かたち し たいめい しゅうし りく い とき な とき りくりゅう の もっ てん ぎょ けんどう へんか おのおの せいめい ただ たいわ ほごう すなわ りてい しゅ しょぶつ い ばんこくことごと やす", "d": "天行は健なり。君子以て自ら強めて息まず。", "rd": "てんこう すこやか くんし もっ みずか つと や", "y": [["潜龍、用ふる勿れ。", "潛龍用ふる勿れとは、陽、下に在ればなり。"], ["見龍、田に在り、大人を見るに利し。", "見龍田に在りとは、德の施し普きなり。"], ["君子終日乾乾、夕に惕若たり、厲けれども咎无し。", "終日乾乾とは、道に反復するなり。"], ["或は躍り、淵に在り、咎无し。", "或は躍り、淵に在りとは、進みて咎无きなり。"], ["飛龍、天に在り、大人を見るに利し。", "飛龍、天に在りとは、大人造るなり。"], ["亢龍、悔い有り。", "亢龍悔有りとは、盈つることは久しかる可からざるなり。"], ["羣龍を見るに首无し、吉。", "天徳は、首たる可からざるなり。"]], "ry": [["せんりょう もち なか", "せんりょう もち なか よう しも あ"], ["けんりょう でん あ たいじん み よろ", "けんりょう でん あ とく ほどこ あまね"], ["くんし しゅうじつ けんけん ゆうべ てきじゃく あやう とが な", "しゅうじつ けんけん みち はんぷく"], ["あるい おど ふち あ とが な", "あるい おど ふち あ すす とが な"], ["ひりょう てん あ たいじん み よろ", "ひりょう てん あ たいじん おこ"], ["こうりょう く あ", "こうりょう くい あ み ひさ べ"], ["ぐんりょう み かしら な きつ", "てん とく かしら べ"]]}, "2": {"k": "坤は元亨利、牝馬の貞。（坤は元に亨る、牝馬の貞に利し。）君子、往く攸有り、先んずれば迷ひ、後るれば主を得。西南に朋を得、東北には朋を喪ふに利し。貞に安んずれば吉。", "rk": "こん げん こう り ひん ば てい こん おおい とお ひんば てい よろ くんし ゆ ところ あ さき まよ おく しゅ う せいなん とも え とうほく とも うしな よろ てい やす きつ", "t": "至れるかな坤元、萬物資りて生ず。乃ち順にして天を承く。坤は厚くして物を載せ、德、无疆に合ふ。含弘光大にして、品物咸く亨る。牝馬は地の類、地を行くこと疆无し。柔順利貞は、君子の行ふ攸なり。先んずれば迷ひて道を失ひ、後るれば順にして常を得。西南に朋を得るは、乃ち類と與に行ふ。東北に朋を喪ふは、乃ち終に慶有り。貞に安んずるの吉は、地の疆无きに應ず。", "rt": "いた こんげん ばんぶつ と しょう すなわ じゅん てん う こん あつ もの の とく むきょう あ がん こう こう だい ひんぶつことご とお ひんば ち るい ち ゆ かぎりな じゅうじゅんりてい くんし おこな ところ さき まよ みち うしな おく じゅん つね う せいなん とも う すなわ るい とも おこな とうほく とも うしな すなわ つい よろこびあ てい やす きつ ち かぎりな おう", "d": "地勢は坤なり。君子以て德を厚くし物を載す。", "rd": "ちせい こん くんし もっ とく あつ もの の", "y": [["霜を履みて堅冰至る。", "霜を履みて堅冰とは、陰始めて凝るなり。其道を馴致すれば、堅冰に至るなり。"], ["直方大なり。習はずして利しからざる无し。", "六二の動は、直にして以て方なり。習はずして利しからざる无しとは、地道光なるなり。"], ["章を含みて貞にす可し。或は王事に從ひ、成す无くして終る有り。", "章を含みて貞にす可しとは、時を以て發するなり。或は王事に從ふとは、知光大なるなり。"], ["嚢を括る。咎も无く譽も无し。", "嚢を括る、咎无しとは、愼みて害あらざるなり。"], ["黄裳、元吉なり。", "黄裳元吉とは、文、中に在るなり。"], ["龍、野に戰ふ。其血玄黄なり。", "龍、野に戰ふとは、其道窮まるなり。"], ["永貞に利し。", "用六永貞は、大を以て終るなり。"]], "ry": [["しも ふ 4けんぴょういた", "しも ふ けんぴょう いんはじ こお そのみち じゅんち けんぴょう いた"], ["ちょく ほう だい なら よろ な", "りくじ どう ちょく もっ ほう なら よろ な ちどう おおい"], ["しょう ふく てい べ あるい おうじ したが な な おわ あ", "しょう ふく てい べ とき もっ はっ あるい おうじ したが ち こう だい"], ["ふくろ くく とが な ほまれ な", "ふくろ くく とがな つつし がい"], ["こうしょう げんきつ", "こうしょう げんきつ ぶん ちゅう あ"], ["りょう や たたか そのち げんおう", "りょう や たたか そのみちきわ"], ["えいてい よろ", "ようりく えいてい だい もっ おわ"]]}, "3": {"k": "屯は元亨利貞。（元に亨る、貞しきに利し。）往く攸有るに用ふる勿れ。侯を建つるに利し。", "rk": "ちゅん げん こう り てい おおい とお ただ よろ ゆ ところ あ もち なか きみ た よろ", "t": "屯は、剛柔始めて交はりて難生ず。險中に動く。大いに亨りて貞し。雷雨の動、滿盈す。天造草昧なり。宜しく侯を建てて寧んぜざるべし。", "rt": "ちゅん ごうじゅう はじ まじ なんしょう けんちゅう うご おお とお ただ らい う どう まん えい てん ぞう そう まい よろ きみ た やす", "d": "雲雷は屯なり。君子以て經綸す。", "rd": "うん らい ちゅん くんし もっ けいりん", "y": [["磐桓す。貞に居るに利し。侯を建つるに利し。", "磐桓すと雖も、志、正しきを行ふなり。貴きを以て賤しきに下る。大いに民を得るなり。"], ["屯如たり、邅如たり。馬に乘りて班如たり。寇するに匪ず、婚媾するなり。女子貞にして字せず、十年にして乃ち字す。", "六二の難は、剛に乘ずればなり。十年にして乃ち字すとは、常に反るなり。"], ["鹿に即きて虞无し、惟だ林中に入る。君子は幾す。舎むに如かず。往けば吝。", "鹿に即きて虞无しとは、以て禽に從ふなり。君子は之を舎む。往けば吝とは窮するなり。"], ["馬に乘りて班如たり。婚媾を求めて往く。吉にして利しからざる无し。", "求めて往くは、明かなるなり。"], ["其膏を屯す。小は貞にして吉。大は貞にして凶。", "其膏を屯すとは、施未だ光ならざるなり。"], ["馬に乘りて班如たり。泣血漣如たり。", "泣血漣如たり。何ぞ長かる可けんや。"]], "ry": [["はんかん てい お よろ きみ た よろ", "はん かん いえど こころざし ただ おこな たか もっ いや くだ おお たみ う"], ["ちゅんじょ てんじょ うま の はんじょ あだ あら こんこう じょしてい あざな じゅうねん すなわ あざな", "りくじ なん ごう じょう じゅうねん すなわ あざな つね かえ"], ["しか つ ぐ な た りんちゅう い くんし き や し ゆ りん", "しか つ ぐ な もっ きん したが くんし これ や ゆ りん きゅう"], ["うま の はんじょ こんこう もと ゆ きつ よろ な", "もと ゆ あきら"], ["そのあぶら ちゅん しょう てい きつ だい てい きょう", "そのあぶら ちゅん ほどこしいま おおい"], ["うま の はんじょ きゅう けつ れんじょ", "きゅうけつ れんじょ なん なが べ"]]}, "4": {"k": "蒙は亨る。我、童蒙に求むるに匪ず、童蒙、我に求む。初筮は告ぐ。再三すれば瀆る。瀆るれば則ち告げず。貞しきに利し。", "rk": "もう とお われ どう もう もと あら どう もう われ もと しょ ぜい つ さい さん けが けが すなわ つ ただ よろ", "t": "蒙は山の下に險有り。險にして止まるは蒙なり。蒙は亨るとは、亨るを以って時中を行ふなり。我、童蒙に求むるに匪ず、童蒙、我に求むとは、志應ずるなり。初筮は告ぐとは、剛中を以てなり。再三すれば瀆る、瀆るれば則ち告げずとは、蒙を瀆すなり。蒙以て正しきを養ふは、聖の功なり。", "rt": "もう やま した けん あ けん とど もう もう とお とお もっ じちゅう おこな われ どう もう もと あら どう もう われ もと こころざしおう しょ ぜい つ ごう ちゅう もっ さいさん けが けが すなわ つ もう けが もう もっ ただ やしな せい こう", "d": "山下に出づる泉は蒙なり。君子以て行を果し徳を育ふ。", "rd": "さんか い いずみ もう くんし もっ おこない はた とく やしな", "y": [["蒙を發く。用て人を刑するに利し。用て桎梏を説きて以て往くは吝。", "用て人を刑するに利しとは、以て法を正すなり。"], ["蒙を包む、吉。婦を納る、吉。子、家を克くす。", "子、家を克くすとは、剛柔接はるなり。"], ["用て女を取る勿れ。金夫を見、躬を有たず。利しき攸无し。", "用て女を取る勿れとは、行、順ならざるなり。"], ["蒙に困しむ、吝。", "蒙に困しむの吝は、獨り實に遠ざかるなり。"], ["童蒙、吉。", "童蒙の吉は、順にして以て巽なるなり。"], ["蒙を撃つ。寇を爲すに利しからず。寇を禦ぐに利し。", "用て寇を禦ぐに利しとは、上下順なるなり。"]], "ry": [["もう ひら もっ ひと けい よろ もっ しつ こく と もっ ゆ りん", "もっ ひと けい よろ もっ ほう ただ"], ["もう つつ きつ ふ い きつ し いえ よ", "し いえ よ ごうじゅう まじ"], ["もっ おんな めと なか きんふ み み たも よろ ところ な", "もっ おんな めと なか おこない じゅん"], ["もう くる りん", "もう くる りん ひと じつ とお"], ["どう もう きつ", "どう もう きつ じゅん もっ そん"], ["もう う あだ な よろ あだ ふせ よろ", "もっ あだ ふせ よろ じょうげ じゅん"]]}, "5": {"k": "需は孚有り。光に亨る。貞にして吉。大川を渉るに利し。", "rk": "じゅ まこと あ おおい とお てい きつ たいせん わた よろ", "t": "需は須つなり。險、前に在るなり。剛健にして陥らず。其義、困窮せず。需は孚有り、光に亨る、貞にして吉とは、天位に位するに、正中を以てするなり。大川を渉るに利しとは、往きて功有るなり。", "rt": "じゅ ま けん まえ あ ごうけん おちい その ぎ こんきゅう じゅ まこと あ おおい とお てい きつ てんい くらい せいちゅう もっ たいせん わた よろ ゆ こう あ", "d": "雲、天に上るは需なり。君子以て飮食宴樂す。", "rd": "くも てん のぼ じゅ くんし もっ いんしょく えんらく", "y": [["郊に需つ。恆を用ふるに利し。咎无し。", "郊に需つとは、難を犯して行かざるなり。恆を用ふるに利し、咎无しとは、未だ常を失はざるなり。"], ["沙に需つ。小しく言有り。終に吉。", "沙に需つとは、衍にして中に在るなり。小しく言有りと雖も、吉を以て終るなり。"], ["泥に需つ。寇の至るを致す。", "泥に需つとは、災、外に在るなり。我より寇を致す。敬愼すれば敗れざるなり。"], ["血に需つ。穴より出づ。", "血に需つとは、順にして以て聽くなり。"], ["酒食に需つ。貞にして吉。", "酒食貞吉とは、中正なるを以てなり。"], ["穴に入る。速かざるの客三人來る有り。之を敬すれば終に吉。", "速かざるの客來る。之を敬すれば終に吉とは、位に當らずと雖も、未だ大いに失はざるなり。"]], "ry": [["こう ま つね もち よろ とが な", "こう ま なん おか ゆ つね もち よろ とが な いま つね うしな"], ["すな ま すこ げん あ つい きつ", "すな ま えん ちゅう あ すこ げん あ いえど きつ もっ おわ"], ["どろ ま あだ いた いた", "どろ ま わざわい そと あ われ あだ いた けいしん やぶ"], ["ち ま あな い", "ち ま じゅん もっ き"], ["しゅし ま てい きつ", "しゅし ていきつ ちゅうせい もっ"], ["あな い まね きゃくさんにん きた あ これ けい つい きつ", "まね きゃくきた これ けい つい きつ くらい あた いえど いま おお うしな"]]}, "6": {"k": "訟は孚有り、窒がり、惕れて中すれば吉、終ふれば凶。大人を見るに利し。大川を渉るに利しからず。", "rk": "しょう まこと あ ふさ おそ ちゅう きつ お きょう たいじん み よろ たいせん わた よろ", "t": "訟は上剛にして下險なり。險にして健なるは訟なり。訟は孚有り、窒がり、惕れて中すれば吉とは、剛來りて中を得るなり。終ふれば凶とは、訟は成す可からざるなり。大人を見るに利しとは、中正を尚ぶなり。大川を渉るに利しからずとは、淵に入るなり。", "rt": "しょう かみごう しもけん けん けん しょう しょう まこと あ ふさ おそ ちゅう きつ ごう きた ちゅう う お きょう しょう な べ たいじん み よろ ちゅうせい たつと たいせん わた よろ ふち い", "d": "天と水と違ひ行くは訟なり。君子以て事を作すに始を謀る。", "rd": "てん みず たが ゆ しょう くんし もっ こと な はじめ はか", "y": [["事とする所を永くせず。小しく言有り。終に吉。", "事とする所を永くせずとは、訟は長くす可からざるなり。小しく言有りと雖も、其辨明かなるなり。"], ["訟ふる克はず、歸りて逋る。其邑人三百戸、眚无し。", "訴ふる克たず、歸りて逋竄するなり。下より上を訟ふ、患至ること掇ふなり。"], ["舊德を食む。貞なれども厲し。終に吉。或は王事に從ひて成す无し。", "舊德を食むとは、上に從ひて吉なるなり。"], ["訟ふる克はず。復りて命に即き、渝りて貞に安んずれば吉。", "復りて命に即き、渝りて貞に安んずとは、失はざるなり。"], ["訟、元吉。", "訟元吉とは、中正を以てなり。"], ["或は之に鞶帯を錫ふ。終朝三たび之を褫はる。", "訟を以て服を受くるは、亦、敬するに足らざるなり。"]], "ry": [["こと ところ なが すこ げん あ つい きつ", "こと ところ なが うったえ なが べ すこ げん あ いえど そのべんあきら"], ["うった あた かえ のが その ゆう じん さん びゃく こ わざわいな", "うった あた かえ ほ ざん しも かみ うった うれいいた ひろ"], ["きゅうとく は てい あやう つい きつ あるい おうじ したが な な", "きゅうとく は かみ したが きつ"], ["うった あた かえ めい つ かわ てい やす きつ", "かえ めい つ かわ てい やす うしな"], ["しょう げんきつ", "しょうげんきつ ちゅうせい もっ"], ["あるい これ はん たい たま しゅうちょう み これ うば", "うったえ もっ ふく う また けい た"]]}, "7": {"k": "師は貞。丈人なれば吉。咎无し。", "rk": "し てい じょうじん きつ とが な", "t": "師は衆なり。貞は正しきなり。能く衆を以て正しければ、以て王たる可し。剛中にして應じ、險を行うて順なり。此れを以て天下を毒すれども、民、之に從ふ。吉にして、又何の咎あらん。", "rt": "し しゅう てい ただ よ しゅう もっ ただ もっ おう べ ごうちゅう おう けん おこの じゅん こ もっ てんか どく たみ これ したが きつ また なん とが", "d": "地中に水有るは師なり。君子以て民を容れ衆を畜ふ。", "rd": "ちちゅう みず あ し くんし もっ たみ い たみ やしな", "y": [["師出づるに律を以てす。否ざれば臧きも凶なり。", "師出づるに律を以てす。律を失へば凶なるなり。"], ["師に在りて中す。吉にして咎无し。王三たび命を錫ふ。", "師に在りて中す、吉とは、天寵を承くるなり。王三たび命を錫ふとは、万邦を懐くるなり。"], ["師或は尸を輿ふ。（師或は輿尸る）凶。", "師或は尸を輿ふとは（師或は輿尸るとは）、大いに功无きなり。"], ["師左き次る。咎无し。", "左き次る、咎无しとは、未だ常を失はざるなり。"], ["田に禽有り。言を執るに利し。咎无し。長子は師を帥ゐぬ。弟子は尸を輿ふ。（弟子は輿尸る）貞なるも凶。", "長子は師を帥ゐぬは、中行を以てなり。弟子は尸を輿ふは（弟子は輿尸るは）、使ふこと當らざるなり。"], ["大君、命あり、國を開き家を承く。小人は用ふる勿れ。", "大君、命有りとは、以て功を正すなり。小人は用ふる勿れとは、必ず國を亂ればなり。"]], "ry": [["し い りつ もっ しから よ きょう", "いくさ い りつ もっ りつ うしな きょう"], ["し あ ちゅう きつ とが な おう み めい たま", "し あ ちゅう きつ てんちょう う おう み いのち たま ばん ぽう なつ"], ["いくさあるい しかばね にな いくさあるい もろもろつかさど きょう", "いくさあるい しかばね にな いくさあるい もろもろつかさど おお こう な"], ["いくさしりぞ やど とが な", "しりぞ やど とが な いま つね うしな"], ["た きん あ げん と よろ とが な ちょうし いくさ ひき ていし しかばね にな ていし もろもろつかさど てい きょう", "ちょうし いくさ ひき ちゅうこう もっ ていし しかばね にな ていし もろもろつかさど つか あた"], ["たいくん めい くに ひら いえ う しょうじん もち なか", "たいくん めい あ もっ こう ただ しょうじん もち なか かなら くに みだ"]]}, "8": {"k": "比は吉。原筮して元永貞なれば、咎无し。寧んぜずして方く來る。後るる夫は凶。", "rk": "ひ きつ げんぜい げんえいてい とが な やす あまね きた おく ふ きょう", "t": "比は吉なり。比は輔くるなり。下順從するなり。原筮して元永貞なれば咎无しとは、剛中なるを以てなり。寧んぜずして方く來るとは、上下應ずるなり。後るる夫は凶とは、其道窮まるなり。", "rt": "ひ きつ ひ たす しもじゅうじゅん げんぜい げんえいてい とが な ごうちゅう もっ やす あまね きた じょうげ おう おく ふ きょう そのみちきわ", "d": "地の上に水有るは比なり。先王以て萬國を建て諸侯を親しむ。", "rd": "ち うえ みず あ ひ せんおう もっ ばんこく た しょこう した", "y": [["孚有り之に比す。咎无し。孚有り缶に盈つ。終に來りて他の吉有り。", "比の初六は、他の吉有るなり。"], ["之に比すること内よりす。貞にして吉。", "之に比すること内よりすとは、自ら失はざるなり。"], ["之に比すること人に匪ず。", "之に比すること人に匪ず、亦傷ましからずや。"], ["外、之に比す。貞にして吉。", "外、賢に比し、以て上に從ふなり。"], ["顯かに比す。王、三軀を用ひ、前禽を失ふ。邑人、誡めず。吉。", "顯かに比するの吉は、位正中なればなり。逆を舎てて順を取り、前禽を失ふなり。邑人、誡めずとは、上、中ならしむるなり。"], ["之に比するに首无し。凶。", "之に比するに首无しとは、終る所无きなり。"]], "ry": [["まこと あ これ ひ とが な まこと あ ほとぎ み つい きた た きつ あ", "ひ しょりく た きつ あ"], ["これ ひ うち てい きつ", "これ ひ うち みずか うしな"], ["これ ひ ひと あら", "これ ひ ひと あら また いた"], ["そと これ ひ てい きつ", "そと けん ひ もっ かみ したが"], ["あきら ひ おう さんく もち ぜん きん うしな ゆうじん いまし きつ", "あきら ひ きつ くらいせいちゅう ぎゃく す じゅん と ぜんきん うしな ゆう じん いまし かみ ちゅう"], ["これ ひ かしら な きょう", "これ ひ かしら な おわ ところ な"]]}, "9": {"k": "小畜は亨る。密雲、雨ふらず、我が西郊よりす。", "rk": "しょうちく とお みつうん あめ わ せいこう", "t": "小畜は、柔、位を得て、上下、之に應ずるを、小畜と曰ふ。健にして巽、剛中にして志行はる。乃ち亨る。密雲、雨ふらずとは、往くを尚ぶなり。我が西郊よりすとは、施未だ行はれざるなり。", "rt": "しょうちく じゅう くらい え じょうげ これ おう しょうちく い けん そん ごうちゅう こころざしおこな すなわ とお みつうん あめ ゆ たつと わ せい こう ほどこしいま おこな", "d": "風、天上を行くは、小畜なり。君子以て文德を懿くす。", "rd": "かぜ てんじょう ゆ しょうちく くんし もっ ぶんとく よ", "y": [["復すること道に自る。何ぞ其れ咎あらん。吉。", "復すること道に自るとは、其義吉なるなり。"], ["牽きて復す。吉。", "牽きて復して中に在り、亦、自ら失はざるなり。"], ["輿輹を説く。夫妻反目す。", "夫妻反目すとは、室を正す能はざるなり。"], ["孚有り、血去り惕出づ。咎无し。", "孚有り惕出づとは、上、志を合はすればなり。"], ["孚有り攣如たり。富みて其鄰を以てす。", "孚有り攣如たりとは、獨り富まざるなり。"], ["既に雨ふり既に處る。德を尚びて載つ。婦は貞なるも厲し。月、望に幾し。君子征けば凶。", "既に雨ふり既に處るとは、德積載するなり。君子征けば凶とは、疑はしき所有るなり。"]], "ry": [["ふく みち よ なん そ とが きつ", "ふく みち よ その ぎ きつ"], ["ひ ふく きつ", "ひ ふく ちゅう あ また みずか うしな"], ["くるまとこばしり と ふさい はんもく", "ふさい はんもく しつ ただ あた"], ["まこと あ ち さ おそれい とが な", "まこと あ おそれ い かみ こころざし あ"], ["まこと あ れんじょ と その となり もっ", "まこと あ れんじょ ひと と"], ["すで あめ すで お とく たつと み ふ てい あやう つき ぼう ちか くんし ゆ きょう", "すで あめ すで お とく せき さい くんし ゆ きょう うたが ところ あ"]]}, "10": {"k": "虎の尾を履む。人を咥はず。亨る。", "rk": "とら お ふ ひと くら とお", "t": "履は、柔、剛を履むなり。説びて乾に應ず。是を以て虎の尾を履み、人を咥はず、亨る。剛中正にして、帝位を履みて疚ましからず、光明なるなり。", "rt": "り じゅう ごう ふ よろこ けん おう ここ もっ とら お ふ ひと くら とお ごう ちゅう せい ていい ふ や こう めい", "d": "上天下澤は履なり。君子以て上下を辯じ、民の志を定む。", "rd": "かみ てん しも たく り くんし もっ じょうげ べん たみ こころざし さだ", "y": [["素履す。往きて咎无し。", "素履の往くは、獨り願ひを行ふなり。"], ["道を履むこと坦坦たり。幽人は貞にして吉。", "幽人は貞にして吉とは、中にして自ら亂れざるなり。"], ["眇にして能く視るとし、跛にして能く履むとす。虎の尾を履む。人を咥ふ。凶。武人、大君と爲る。", "眇にして能く視るとするも、以て明有るに足らざるなり。跛にして能く履むとするも、以て與に行くに足らざるなり。人を咥ふの凶は、位、當らざるなり。武人、大君と爲るは、志剛なるなり。"], ["虎の尾を履む。愬愬たり。終に吉。", "愬愬たり、終に吉とは、志行はるるなり。"], ["夬履す。貞なるも厲し。", "夬履す、貞なるも厲しとは、位正しく當ればなり。"], ["履を視て祥を考ふ。其れ旋れば元吉。", "元吉にして上に在り、大に慶有るなり。"]], "ry": [["そ り ゆ とが な", "そ り ゆ ひと ねが おこな"], ["みち ふ たんたん ゆう じん てい きつ", "ゆう じん てい きつ ちゅう みずか みだ"], ["すがめ よ み あしなえ よ ふ とら お ふ ひと くら きょう ぶじん たいくん な", "すがめ よ み もっ めい あ た あしなえ よ ふ もっ とも ゆ た ひと くら きょう くらい あた ぶじん たいくん な こころざしごう"], ["とら お ふ さく さく つい きつ", "さく さく つい きつ こころざしおこな"], ["かいり てい あやう", "かいり てい あやう くらいただ あた"], ["り み しょう かんが そ めぐ げん きつ", "げんきつ かみ あ おおい よろこびあ"]]}, "11": {"k": "泰は小往き大來る。吉にして亨る。", "rk": "たい しょう ゆ だい きた きつ とお", "t": "泰は小往き大來る、吉にして亨るとは、則ち是れ天地交はりて萬物通ずるなり、上下交はりて其志同じきなり、内は陽にして外は陰、内は健にして外は順、内は君子にして外は小人、君子の道長じ、小人の道消するなり。", "rt": "たい しょう ゆ だい きた きつ とお すなわ こ てん ち まじ ばんぶつ つう じょうげ まじ そのこころざしおな うち よう そと いん うち けん そと じゅん うち くんし そと しょうじん くんし みちちょう しょうじん みちしょう", "d": "天地交はるは泰なり。后以て天地の道を財成し、天地の宜を輔相し、以て民を左右す。", "rd": "てんち まじ たい きみ もっ てんち みち さい せい てんち ぎ ほしょう もっ たみ さゆう", "y": [["茅を抜くに茹たり。其彙を以てす。征きて吉。", "茅を抜き征きて吉とは、志、外に在るなり。"], ["荒を包み、馮河を用ひ、遐きを遺れず、朋亡はれ、中行に尚ふを得。", "荒を包み、中行に尚ふを得とは、以て光大なるなり。"], ["平かなるとして陂かざる无く、往くとして復らざる无し。艱貞なれば咎无し。恤うる勿れ、其れ孚あれ。食に于て福有り。", "往くして復らざる无しとは、天地際はるなり。"], ["翩翩たり。富めりとせずして其鄰を以てす。戒めずして以て孚あり。", "翩翩として富めりとせずとは、皆、實を失ふなり。戒めずして以て孚ありとは、中心願ふなり。"], ["帝乙、妹を帰がしむ。以て祉あり。元吉。", "以て祉あり元吉とは、中にして以て願を行ふなり。"], ["城、隍に復る。師を用ふる勿れ。邑より命を告ぐ。貞なるも吝。", "城、隍に復るとは、其命亂るるなり。"]], "ry": [["ちがや ぬ じょ そのたぐい もっ ゆ きつ", "ちがや ぬ ゆ きつ こころざし そと あ"], ["こう つつ ひょうか もち とお わす とも うしな ちゅうこう あ う", "こう つつ ちゅうこう あ う もっ こう だい"], ["たいら かたむ な ゆ かえ な かんてい とが な うれ なか そ まこと しょく おい さいわいあ", "ゆ かえ な てんち まじ"], ["へんべん と そのとなり もっ いまし もっ まこと", "へんべん と みな じつ うしな いまし もっ まこと ちゅうしんねが"], ["ていいつ いもうと とつ もっ さいわい げんきつ", "もっ さいわい げんきつ ちゅう もっ ねがい おこな"], ["しろ からぼり かえ いくさ もち なか ゆう めい つ てい りん", "しろ からぼり かえ そのめい みだ"]]}, "12": {"k": "之を否ぐは人に匪ず。君子の貞に利しからず。大往き小來る。", "rk": "これ ふさ ひと あら くんし てい よろ だい ゆ しょう きた", "t": "之を否ぐは人に匪ず、君子の貞に利しからず、大往き小來るとは、則ち是れ天地、交はらずして、萬物、通ぜざるなり。上下、交はらずして、天下、邦无きなり。内は陰にして外は陽、内は柔にして外は剛、内は小人にして外は君子、小人の道長じ、君子の道消するなり。", "rt": "これ ふさ ひと あら くんし てい よろ だい ゆ しょうきた すなわ こ てん ち まじ ばんぶつ つう じょうげ まじ てんか くに な うち いん そと よう うち じゅう そと ごう うち しょうじん そと くんし しょうじん みちちょう くんし みちしょう", "d": "天地交はらざるは否なり。君子以て德を儉にし難を辟け、榮するに祿を以てす可からず。", "rd": "てんち まじ ひ くんし もっ とく つづまやか なん さ えい ろく もっ べ", "y": [["茅を抜くに茹たり。其彙を以てす。貞なれば吉にして亨る。", "茅を抜く、貞なれば吉とは、志、君に在るなり。"], ["包承す。小人は吉。大人は否がりて亨る。", "大人は否がりて亨るとは、羣を亂さざるなり。"], ["包羞す。", "包羞すとは、位、當らざるなり。"], ["命有り咎无し。疇、祉に離く。", "命有り咎无しとは、志行はるるなり。"], ["否を休む。大人は吉。其れ亡びなん、其れ亡びなん、苞桑に繫がる。", "大人の吉は、位正しく當るなり。"], ["否を傾く。先には否がり後には喜ぶ。", "否終れば則ち傾く。何ぞ長かる可けんや。"]], "ry": [["ちがや ぬ じょ そのたぐい もっ てい きつ とお", "ちがや ぬ てい きつ こころざし きみ あ"], ["ほうしょう しょうじん きつ たいじん ふさ とお", "たいじん ふさ とお ぐん みだ"], ["ほうしゅう", "ほうしゅう くらい あた"], ["めい あ とが な たぐい さいわい つ", "めい あ とが な こころざしおこな"], ["ひ や たいじん きつ そ ほろ そ ほろ ほう そう つな", "たいじん きつ くらいただ あた"], ["ひ かたむ さき ふさ のち よろこ", "ひ おわ すなわ かたむ なん なが べ"]]}, "13": {"k": "人に同じくするに野に于てす。亨る。大川を渉るに利し。君子の貞に利し。", "rk": "ひと おな や おい とお たいせん わた よろ くんし てい よろ", "t": "同人は、柔、位を得、中を得て乾に應ずるを、同人と曰う。同人に曰く、人に同じくするに野に于てす。亨る。大川を渉るに利しとは、乾の行なり。文明にして以て健、中正にして應ず、君子の正しきなり。唯だ君子のみ能く天下の志を通ずと爲す。", "rt": "どうじん じゅう くらい え ちゅう え けん おう どうじん い どうじん いわ ひと おな や おい とお たいせん わた よろ けん おこない ぶん めい もっ けん ちゅうせい おう くんし ただ た くんし よ てんか こころざし つう な", "d": "天と火とは同人なり。君子以て族を類し物を辯ず。", "rd": "てん ひ どうじん くんし もっ ぞく るい もの べん", "y": [["人に同じくするに門に于てす。咎无し。", "門を出でて人に同じくす。又誰か咎めんや。"], ["人に同じくするに宗に于てす。吝。", "人に同じくするに宗に于てすとは、吝なる道なり。"], ["戎を莽に伏し、其高陵に升る。三歳まで興らず。", "戎を莽に伏すとは、敵剛なればなり、三歳まで興らず。安んぞ行かんや。"], ["其墉に乘る。攻むる克はず。吉。", "其墉に乘るは、義、克はざるなり。其の吉なるは、則ち困みて反ればなり。"], ["人に同じくするに、先には號咷して後には咲ふ。大師克ちて相遇ふ。", "同人の先は、中直なるを以てなり。大師相遇ふとは、相克つを言ふなり。"], ["人に同じくするに郊に于てす。悔无し。", "人に同じくするに郊に于てすとは、志未だ得ざるなり。"]], "ry": [["ひと おな もん おい とが な", "もん い ひと おな まただれ とが"], ["ひと おな そう おい りん", "ひと おな そう おい りん みち"], ["つわもの くさむら ふく その こう りょう のぼ さん さい おこ", "つわもの くさむら ふく てき ごう さんさい おこ いずく ゆ"], ["そのかき のぼ せ あた きつ", "そのかき のぼ ぎ あた そ きつ すなわ くるし かえ"], ["ひと おな さき ごう とう のち わら たいし か あい あ", "どうじん さき ちゅうちょく もっ たい し あい あ あい か い"], ["ひと おな こう おい くい な", "ひと おな こう おい こころざしいま え"]]}, "14": {"k": "大有は、元に亨る。", "rk": "たいゆう おおい とお", "t": "大有は、柔、尊位を得、大中にして、上下、之に應ずるを、大有と曰う。其德は剛健にして文明、天に應じて時に行ふ。是を以て元に亨る。", "rt": "たい ゆう じゅう そんい え だいちゅう じょうげ これ おう たい ゆう い その とく ごう けん ぶんめい てん おう とき おこな ここ もっ おおい とお", "d": "火、天上に在るは、大有なり。君子以て惡を遏め善を揚げ、天の休命に順ふ。", "rd": "ひ てんじょう あ たいゆう くんし もっ あく とど ぜん あ てん きゅうめい したが", "y": [["害に交はる无し。咎あるに匪ず。艱めば則ち咎无し。", "大有の初九は、害に交はる无きなり。"], ["大車以て載す。往く攸有り。咎无し。", "大車以て載すとは、中に積みて敗れざるなり。"], ["公用て天子に亨せらる。（公用って天子に亨す）小人は克はず。", "公用て天子に亨せらる（公用って天子に享す）。小人は害あるなり。"], ["其の彭なるに匪ず。咎无し。", "其の彭なるに匪ず、咎无しとは、明辯晢なるなり。"], ["厥孚、交如たり、威如たり。吉。", "厥孚交如たりとは、信以て志を發するなり。威如の吉は、易にして備ふる无きなり。"], ["天より之を祐く。吉にして利しからざる无し。", "大有の上吉は、天より祐くるなり。"]], "ry": [["がい まじ な とが あら なや すなわ とが な", "たいゆう しょきゅう がい まじ な"], ["たいしゃ もっ の ゆ ところ あ とが な", "たいしゃもっ の うち つ やぶ"], ["こう もっ てんし きょう こう もっ てんし きょう しょうじん あた", "こう もっ てんし きょう こう もっ てんし きょう しょうじん がい"], ["そ さかん あら とが な", "そ さかん あら とが な めいべんあきらか"], ["そのまこと こう じょ い じょ きつ", "その まこと こうじょ しん もっ こころざし はっ い じょ きつ い そな な"], ["てん これ たす きつ よろ な", "たいゆう じょうきつ てん たす"]]}, "15": {"k": "謙は亨る。君子、終有り。", "rk": "けん とお くんし おわり あ", "t": "謙は、亨る。天道は下済して光明なり。地道は卑くして上行す。天道は盈を虧きて謙に益し、地道は盈を變じて謙に流れ、鬼神は盈を害して謙に福し、人道は盈を惡みて謙を好む。謙は尊くして光り、卑くして踰ゆ可からず。君子の終なり。", "rt": "けん とお てんどう かせい こうめい ちどう ひく じょうこう てんどう えい か けん ま ちどう えい へん けん なが きしん えい がい けん さいわい じんどう えい にく けん この けん とうと ひか ひく こ べ くんし おわり", "d": "地中に山有るは謙なり。君子以て多きを裒らし寡きを益し、物を稱り施を平かにす。", "rd": "ちちゅう やま あ けん くんし もっ おお へ すくな ま もの はか ほどこし たいら", "y": [["謙謙す。君子用て大川を渉る。吉。", "謙謙する君子は卑にして以て自ら牧ふなり。"], ["鳴謙す。貞にして吉。", "鳴謙す、貞にして吉とは、中心得るなり。"], ["勞謙す。君子、終有り。吉。", "勞謙する君子は、萬民服するなり。"], ["謙を撝ふに利しからざる无し。（利しからざる无し。謙を撝ふ。）", "謙を撝ふに利しからざる无し（利しからざる无し、謙を撝ふ）とは、則に違はざるなり。"], ["富めりとせずして其鄰と以てす。用て侵伐するに利し。利しからざる无し。", "用て侵伐するに利しとは、服せざるを征するなり。"], ["鳴謙す。用て師を行り邑國を征するに利し。", "鳴謙すとは、志未だ得ざるなり。用って師を行り邑國を征す可きなり。"]], "ry": [["めいけん くんし もっ たいせん わた きつ", "けんけん くんし ひ もっ みずか やしな"], ["めいけん てい きつ", "めいけん てい きつ ちゅうしん う"], ["ろうけん くんし おわり あ きつ", "ろう けん くんし ばんみん ふく"], ["けん ふる よろ な よろ な けん ふる", "けん ふる よろ な よろ な けん ふる のり たが"], ["と そのとなり もっ もっ しんばつ よろ よろ な", "もっ しんばつ よろ ふく せい"], ["めいけん もっ いくさ や ゆうこく せい よろ", "めいけん こころざしいま え もっ いくさ や ゆう こく せい べ"]]}, "16": {"k": "豫は侯を建て師を行るに利し。", "rk": "よ きみ た いくさ や よろ", "t": "豫は剛應ぜられて志行はる。順以て動くは豫なり。豫は順以て動く。故に天地も之の如し、而るを況んや侯を建て師を行るをや。天地は順を以て動く。故に日月、過たずして、四時、忒はず。聖人は順を以て動く。則ち刑罰清くして民服す。豫の時義大なるかな。", "rt": "よ ごう おう こころざしおこな じゅんもっ うご よ よ じゅんもっ うご ゆえ てんち かく ごと しか いわ きみ た いくさ や てんち じゅん もっ うご ゆえ じつげつ あやま しいじ たが せいじん じゅん もっ うご すなわ けいばつきよ たみふく よ じ ぎ おおい", "d": "雷、地を出でて奮ふは豫なり。先王以て樂を作り德を崇び、之を上帝に殷薦し、以て祖考を配す。", "rd": "らい ち い ふる よ せんのう もっ がく つく とく たつと これ じょうてい いんせん もっ そ こう はい", "y": [["鳴豫す。凶。", "初六の鳴豫は、志窮まりて凶なるなり。"], ["石に介す。日を終へず。貞にして吉。", "日を終へず、貞にして吉とは、中正なるを以てなり。"], ["旰豫す。悔ゆること遅ければ悔有り。", "旰豫す、悔有りとは、位、當らざるなり。"], ["由豫す。大いに得る有り。疑ふ勿れ。朋盍ひ簪まる。", "由豫す、大いに得る有りとは、志大いに行はるなり。"], ["貞にして疾む。恒にして死せず。", "六五の貞にして疾むは、剛に乘ずればなり。恆にして死せざるは、中未だ亡びざればなり。"], ["冥豫す。成れども渝る有れば、咎无し。", "冥豫して上に在り。何ぞ長かる可けんや。"]], "ry": [["めい よ きょう", "しょりく めいよ こころざしきわ きょう"], ["いし かい ひ お てい きつ", "ひ お てい きつ ちゅうせい もっ"], ["く よ く おそ くい あ", "く よ くい あ くらい あた"], ["ゆう よ おお う あ うたが なか とも あ あつ", "ゆう よ おお う あ こころざしおお おこな"], ["てい や つね し", "りくご てい や ごう じょう つね し ちゅういま ほろ"], ["めい よ な かわ あ とが な", "めい よ かみ あ なん なが べ"]]}, "17": {"k": "随は元に亨る、貞しきに利し。咎无し。", "rk": "ずい おおい とお ただ よろ とが な", "t": "随は剛來りて柔に下り、動きて説ぶは随なり。大いに亨り、貞しくして咎无し、而して天下、時に随ふ。時に随ふの義大なるかな。", "rt": "ずい ごう きた じゅう くだ うご よろこ ずい おお とお ただ とが な しか てん か とき したが とき したが ぎ おおい", "d": "澤の中に雷有るは随なり。君子以て晦きに嚮ひて入りて宴息す。", "rd": "さわ なか かみなり あ ずい くんし もっ くら むか い えん そく", "y": [["官、渝る有り。貞にして吉。門を出でて交はれば功有り。", "官、渝る有りとは、正しきに從へば吉なるなり。門を出でて交はれば功有りとは、失はざるなり。"], ["小子に係れば、丈夫を失ふ。", "小子に係るとは、兼ね與せざるなり。"], ["丈夫に係れば、小子を失ふ。随ひて求むる有れば得。貞に居るに利し。", "丈夫に係るとは、志、下を舎つるなり。"], ["隨ひて獲る有り。貞なるも凶。孚有り道に在り、以て明かならば何の咎あらん。", "随ひて獲る有りとは、其義凶なるなり。孚有り道に在りとは、明の功なり。"], ["嘉に孚あり。吉。", "嘉に孚あり吉とは、位正中なればなり。"], ["之を拘係し、乃ち從って之を維ぐ。王用って西山に亨す。", "之を拘係すとは、上にして窮まるなり。"]], "ry": [["かん かわ あ てい きつ もん い まじ こう あ", "かん かわ あ ただ したが きつ もん い まじ こう あ うしな"], ["しょうし かか じょうふ うしな", "しょうし かか か くみ"], ["じょうふ かか しょうし うしな したが もと あ う てい お よろ", "じょうふ かか こころざし しも す"], ["したが う あ てい きょう まこと あ みち あ もっ あきら なん とが", "したが う あ その ぎ きょう まこと あ みち あ めい こう"], ["か まこと きつ", "か まこと きつ くらいせいちゅう"], ["これ こう けい すなわ したが これ つな おう もっ せい ざん きょう", "これ こう けい かみ きわ"]]}, "18": {"k": "蠱は元に亨る。大川を渉るに利し。甲に先だつこと三日、甲に後るること三日。", "rk": "こ おおい とお たいせん わた よろ こう さき みっか こう おく みっか", "t": "蠱は剛上りて柔下る。巽にして止まるは蠱なり。蠱は元に亨りて、天下治まるなり。大川を渉るに利しとは、往きて事有るなり。甲に先だつこと三日、甲に後るること三日とは、終れば則ち始有り、天行なり。", "rt": "こ ごう のぼ じゅう くだ そん とど こ こ おおい とお てんか おさ たいせん わた よろ ゆ こと あ こう さき みっか こう おく みっか おわ すなわ はじめ あ てんこう", "d": "山の下に風有るは蠱なり。君子以て民を振ひ徳を育ふ。", "rd": "やま した かぜ あ こ くんし もっ たみ ふる とく やしな", "y": [["父の蠱に幹たり。子有り、考（亡父）、咎无し。厲けれども終に吉。", "父の蠱に幹たりとは、意、考に承くるなり。"], ["母の蠱に幹たり。貞にす可からず。", "母の蠱に幹たりとは、中道を得るなり。"], ["父の蠱に幹たり、小しく悔有り。大なる咎无し。", "父の蠱に幹たりとは、終に咎无きなり。"], ["父の蠱を裕かなり。往きて吝を見る。", "父の蠱に裕かなりとは、往きて未だ得ざるなり。"], ["父の蠱に幹たり。用って譽あり。", "父に幹たり、用って譽ありとは、承くるに徳を以てするなり。"], ["王侯に事へず、其事を高尚にす。", "王侯に事へず、志、則る可きなり。"]], "ry": [["ちち こ かん こ あ ちち とが な あやう つい きつ", "ちち こ かん い こう う"], ["はは こ かん てい べ", "はは こ かん ちゅうどう う"], ["ちち こ かん すこ くい あ だい とが な", "ちち こ かん つい とが な"], ["ちち こ ゆるや ゆ りん み", "ちち こ ゆるや ゆ いま え"], ["ちち こ かん もっ ほまれ", "ちち かん もっ ほまれ う とく もっ"], ["おう こう つか その こと こう しょう", "おう こう つか こころざし のっと べ"]]}, "19": {"k": "臨は元に亨る。貞しきに利し。八月に至りて凶有り。", "rk": "りん おおい とお ただ よろ はちがつ いた きょう あ", "t": "臨は剛浸くにして長じ、説びて順、剛中にして應じ、大いに亨りて以て正し。天の道なり。八月に至りて凶有りとは、消すること久しからざるなり。", "rt": "りん ごう ようや ちょう よろこ じゅん ごう ちゅう おう おお とお もっ ただ てん みち はち がつ いた きょう あ しょう ひさ", "d": "澤の上に地有るは臨なり。君子以て教へ思ふこと窮まり无く、民を容れ保んずること疆无し。", "rd": "さわ うえ ち あ りん くんし もっ おし おも きわ な たみ い やす かぎり な", "y": [["咸臨す。貞にして吉。", "咸臨す、貞にして吉とは、志、正しきを行ふなり。"], ["咸臨す。吉にして利しからざる无し。", "咸臨す、吉にして利しからざる无しとは、未だ命に順はざるなり。"], ["甘臨す。利しき攸无し。既に之を憂ふれば、咎无し。", "甘臨すとは、位、當らざるなり。既に之を憂ふれば、咎、長からざるなり。"], ["至臨す。咎无し。", "至臨す、咎无しとは、位當ればなり。"], ["知臨す。大君の宜しきなり。吉。", "大君の宜しきとは、中を行ふの謂なり。"], ["敦臨す。吉。咎无し。", "敦臨の吉は、志、内に在るなり。"]], "ry": [["かんりん てい きつ", "かんりん てい きつ こころざし ただ おこな"], ["かんりん きつ よろ な", "かんりん きつ よろ な いま めい したが"], ["かんりん よろ ところ な すで これ うれ とが な", "かんりん くらい あた すで これ うれ とが なが"], ["し りん とが な", "し りん とが な くらいあた"], ["ちりん たいくん よろ きつ", "たいくん よろ ちゅう おこな いい"], ["とん りん きつ とが な", "とん りん きつ こころざし うち あ"]]}, "20": {"k": "觀は盥して薦めず、孚有り顒若たり。", "rk": "かん かん すす まこと あ ぎょうじゃく", "t": "大觀、上に在り、順にして巽、中正にして以て天下を觀る。觀は盥ひて、薦めず、孚有り顒若たりとは、下觀て化するなり。天の神道を觀るに、四時、忒はず。聖人、神道を以て教を設けて、天下服す。", "rt": "たい かん かみ あ じゅん そん ちゅうせい もっ てんか み かん てあら すす まこと あ ぎょうじゃく しも み か てん しん どう み しいじ たが せいじん しんどう もっ おしえ もう てんか ふく", "d": "風、地の上を行くは觀なり。先王以て方を省み民を觀て教を設く。", "rd": "かぜ ち うえ ゆ かん せんのう もっ ほう かえり たみ み おしえ もう", "y": [["童觀す。小人は、咎无し。君子は吝。", "初六の童觀は、小人の道なり。"], ["闚觀す。女の貞に利し。", "闚觀す、女の貞は、亦、醜づ可きなり。"], ["我が生を觀て進退す。", "我が生を觀て進退すとは、未だ道を失はざるなり。"], ["國の光を觀る。用って王に賓たるに利し。", "國の光を觀るとは、賓たるを尚ぶなり。"], ["我が生を觀る。君子なれば咎无し。", "我が生を觀るとは、民を觀るなり。"], ["其生を觀る。君子なれば咎无し。", "其生を觀るとは、志、未だ平かならざるなり。"]], "ry": [["どう かん しょうじん とが な くんし りん", "しょりく どう かん しょうじん みち"], ["き かん おんな てい よろ", "き かん おんな てい また は べ"], ["わ せい み しん たい", "わ せい み しんたい いま みち うしな"], ["くに ひかり み もっ おう ひん よろ", "くに ひかり み ひん たつと"], ["わ せい み くんし とがな", "わ せい み たみ み"], ["その せい み くんし とがな", "そのせい み こころざし いま たいら"]]}, "21": {"k": "噬嗑は亨る。獄を用ふるに利し。", "rk": "ぜい こう とお ごく もち よろ", "t": "頤中に物有るは噬嗑と曰う。噬嗑して亨る。剛柔分れ、動きて明かなり。雷電合して章かなり。柔、中を得て上行す。位に當らずと雖も、獄を用ふるに利しきなり。", "rt": "いちゅう もの あ ぜいこう い ぜいこう とお ごうじゅう わか うご あきら らいでん がっ あきら じゅう ちゅう え じょうこう くらい あた いえど ごく もち よろ", "d": "雷電は噬嗑なり。先王以て罰を明かにして法を勑ふ。", "rd": "らいでん ぜいこう せんのう もっ ばつ あきら ほう ととの", "y": [["校を屨みて趾を滅す。咎无し。", "校を屨みて趾を滅すとは、行かざるなり。"], ["膚を噬みて鼻を滅す。咎无し。", "膚を噬みて鼻を滅すとは、剛に乘ずればなり。"], ["腊肉を噬み、毒に遇ふ。小しく吝。咎无し。", "毒に遇ふとは、位當らざればなり。"], ["乾胏を噬み、金矢を得。艱貞に利し。吉。", "艱貞に利し、吉とは、未だ光ならざるなり。"], ["乾肉を噬み、黄金を得。貞にして厲む。咎无し。", "貞にして厲む、咎无しとは、當を得ればなり。"], ["校を何ひて耳を滅す。凶。", "校を何ひて耳を滅すとは、聽くこと明かならざるなり。"]], "ry": [["こう ふ あし めっ とが な", "こう ふ あし めっ ゆ"], ["ふ か はな めっ とが な", "ふ か はな めっ ごう じょう"], ["せき にく か どく あ すこ りん とが な", "どく あ くらい あた"], ["かん し か きん し う かんてい よろ きつ", "かんてい よろ きつ いま おおい"], ["かんにく か おう ごん う てい あやぶ とが な", "てい あやぶ とが な とう う"], ["こう にな みみ めっ きょう", "こう にな みみ めっ き あきら"]]}, "22": {"k": "賁は亨る。小しく往く攸有るに利し。", "rk": "ひ とお すこ ゆ ところ あ よろ", "t": "賁は亨る。柔來りて剛を文る、故に亨る。剛を分ちて上りて柔を文る、故に小しく往く攸有るに利し。天文なり。文明にして以て止まるは、人文なり。天文を觀て、以て時變を察し、人文を觀て、以て天下を化成す。", "rt": "ひ とお じゅう きた ごう かざ ゆえ とお ごう わか のぼ じゅう かざ ゆえ すこ ゆ ところ あ よろ てんもん ぶんめい もっ とど じんぶん てん もん み もっ じ へん さっ じん ぶん み もっ てん か か せい", "d": "山の下に火有るは賁なり。君子以て庶政を明かにし、敢て獄を折むる无し。", "rd": "やま した ひ あ ひ くん し もっ しょ せい あきら あえ ごく さだ な", "y": [["其趾を賁る。車を舍てて徒す。", "車を舎てて徒すとは、義、乘らざるなり。"], ["其須を賁る。", "其須を賁るとは、上と與に興るなり。"], ["賁如たり濡如たり。永貞にして吉。", "永貞の吉は、終に之を陵ぐ莫きなり。"], ["賁如たり皤如たり、白馬翰如たり。寇するに匪ず婚媾するなり。", "六四は、位に當りて疑ふなり。寇するに匪ず婚媾するなりとは、終に尤无きなり。"], ["丘園に賁る。束帛戔戔たり。吝なれども終に吉。", "六五の吉は、喜び有るなり。"], ["白賁なり。咎无し。", "白賁なり、咎无しとは、上、志を得るなり。"]], "ry": [["そのあし かざ くるま す と", "くるま す と ぎ の"], ["そのあごひげ かざ", "そのあごひげ かざ かみ とも おこ"], ["ひじょ じゅじょ えいてい きつ", "えいてい きつ つい これ しの な"], ["ひ じょ は じょ はく ば かん じょ あだ あら こんこう", "りくし くらい あた うたが あだ あら こんこう ついに とが な"], ["きゅうえん かざ そくはく せんせん りん つい きつ", "りくご きつ よろこ あ"], ["はく ひ とが な", "はく ひ とが な じょう こころざし う"]]}, "23": {"k": "剝は往く攸有るに利しからず。", "rk": "はく ゆ ところ あ よろ", "t": "剝は剝ぐなり。柔、剛を變ずるなり。往く攸有るに利しからず、小人長ずればなり。順にして之に止まる。象を觀るなり。君子の消息盈虚を尚ぶ。天行なり。", "rt": "はく は じゅう ごう へん ゆ ところ あ よろ しょうじんちょう じゅん これ とど しょう み くんし しょうそく えいきょ たつと てん こう", "d": "山地に附くは剝なり。上以て下を厚くし宅を安んず。", "rd": "やま ち つ はく かみ もっ しも あつ たく やす", "y": [["牀を剝するに足を以てす。貞を蔑ぼす。凶。", "牀を剝するに足を以てすとは、以て下を滅ぼすなり。"], ["牀を剝するに辯を以てす。貞を蔑ぼす。凶。", "牀を剝するに辯を以てすとは、未だ與有らざるなり。"], ["之を剝す。咎无し。", "之を剝す、咎无しとは、上下を失へばなり。"], ["牀を剝するに膚を以てす。凶。", "牀を剝するに膚を以てすとは、切に災に近きなり。"], ["魚を貫く。宮人を以て寵せらる。利しからざる无し。", "宮人を以て寵せらるとは、終に尤无きなり。"], ["碩果、食はれず。君子は輿を得、小人は廬を剝す。", "君子は輿を得とは、民の載する所なり。小人は廬を剝すとは、終に用ふ可からざるなり。"]], "ry": [["しょう はく あし もっ てい ほろ きょう", "しょう はく あし もっ もっ しも ほろ"], ["しょう はく べん もっ てい ほろ きょう", "しょう はく べん もっ いま よ あ"], ["これ はく とが な", "これ はく とが な じょうげ うしな"], ["しょう はく はだえ もっ きょう", "しょう はく はだえ もっ せつ わざわい ちか"], ["うお つらぬ きゅうじん もっ ちょう よろ な", "きゅうじん もっ ちょう つい とが な"], ["せき か く くん し くるま う しょうじん ろ はく", "くん し くるま う たみ の ところ しょうじん ろ はく つい もち べ"]]}, "24": {"k": "復は亨る。出入、疾无く、朋來りて咎无し。其道に反復し、七日にして來り復る。往く攸有るに利し。", "rk": "ふく とお しゅつにゅう やまい な とも きた とが な その みち はん ぷく なのか きた かえ ゆ ところ あ よろ", "t": "復は亨るとは、剛反ればなり。動きて順を以て行く。是を以て出入、疾无く、朋來りて咎无し。其道に反復し、七日にして來り復るとは、天行なり。往く攸有るに利しとは、剛長ずればなり。復は其れ天地の心を見るか。", "rt": "ふく とお ごう かえ うご じゅん もっ ゆ ここ もっ しゅつにゅう やまい な とも きた とが な その みち はんぷく なのか きた かえ てんこう ゆ ところ あ よろ ごう ちょう ふく そ てん ち こころ み", "d": "雷、地中に在るは復なり。先王以て至日に關を閉ぢ、商旅、行かず、后、方を省みず。", "rd": "らい ちちゅう あ ふく せん のう もっ しじつ せき と しょう りょ ゆ きみ ほう かえり", "y": [["遠からずして復る。悔に祗る无し。元吉。", "遠からざるの復は、以て身を修むるなり。"], ["休復す。吉。", "休復の吉は、仁に下るを以てなり。"], ["頻に復る。厲けれども咎无し。", "頻復の厲きは、義、咎无きなり。"], ["中行にして獨り復る。", "中行にして獨り復るは、以て道に從ふなり。"], ["敦く復る。悔无し。", "敦く復る、悔无しとは、中にして以て自ら考すなり。"], ["復るに迷ふ。凶。災眚有り。用って師を行れば、終に大敗有り。其國君を以てす。凶。十年に至るまで征する克はず。", "復るに迷ふの凶は、君道に反すればなり。"]], "ry": [["とお かえ くい いた な げん きつ", "とお ふく もっ み おさ"], ["きゅうふく きつ", "きゅうふく きつ じん くだ もっ"], ["しきり かえ あやう とが な", "ひん ぷく あやう ぎ とが な"], ["ちゅう こう ひと かえ", "ちゅうこう ひと かえ もっ みち したが"], ["あつ かえ くい な", "あつ かえ くい な ちゅう もっ みずか な"], ["かえ まよ きょう さいせい あ もっ いくさ や つい たいはい あ その こく くん もっ きょう じゅうねん いた せい あた", "かえ まよ きょう くん どう はん"]]}, "25": {"k": "无妄は、元に亨る、貞しきに利し。其れ正しきに匪ざれば眚有り。往く攸有るに利しからず。", "rk": "む ぼう おおい とお ただ よろ そ ただ あら わざわい あ ゆ ところ あ よろ", "t": "无妄は、剛、外より來りて、内に主と爲り、動きて健、剛中にして應じ、大いに亨りて以て正し。天の命なり。其れ正しきに匪ざれば眚有り、往く攸有るに利しからずとは、无妄の往くは何に之かん。天命、祐けず、行かんや。", "rt": "む ぼう ごう そと きた うち しゅ な うご けん ごうちゅう おう おお とお もっ ただ てん めい そ ただ あら わざわいあ ゆ ところ あ よろ む ぼう ゆ いずく ゆ てん めい たす ゆ", "d": "天の下に雷行き、物與无妄なり。先王以て茂めて時に對して萬物を育す。", "rd": "てん した らい ゆ もの みな む ぼう せん のう もっ つと とき たい ばんぶつ いく", "y": [["无妄なり。往きて吉。", "无妄の往くは、志を得るなり。"], ["耕獲せず、菑畬せず。則ち往く攸有るに利し。", "耕獲せずとは、未だ富まざるなり。"], ["无妄の災なり。或は之が牛を繋ぐ。行人の得るは、邑人の災なり。", "行人、牛を得るは、邑人の災なり。"], ["貞にす可し。咎无し。", "貞にす可し、咎无しとは、固より之を有するなり。"], ["无妄の疾なり。藥する勿れ、喜有り。", "无妄の藥は、試ふ可からざるなり。"], ["无妄なり。行けば眚有り。利しき攸无し。", "无妄の行くは、窮まるの災なり。"]], "ry": [["む ぼう ゆ きつ", "む ぼう ゆ こころざし う"], ["こう かく し よ すなわ ゆ ところ あ よろ", "こう かく いま と"], ["む ぼう わざわい あるい これ うし つな こう じん う ゆう じん わざわい", "こう じん うし う ゆう じん わざわい"], ["てい べ とが な", "てい べ とが な もと これ ゆう"], ["む ぼう やまい くすり なか よろこびあ", "む ぼう くすり もち べ"], ["む ぼう ゆ わざわいあ よろ ところ な", "む ぼう ゆ きわ わざわい"]]}, "26": {"k": "大畜は、貞しきに利し。家食せず。吉。大川を渉るに利し。", "rk": "たいちく ただ よろ かしょく きつ たいせん わた よろ", "t": "大畜は剛健篤實にして、輝光日々に新なり。其德、剛上りて賢を尚び、能く健を止む。大いに正しきなり。家食せず、吉とは、賢を養ふなり。大川を渉るに利しとは、天に應ずるなり。", "rt": "たい ちく ごう けん とく じつ き こう ひ び あらた その とく ごう のぼ けん たつと よ けん とど おお ただ か しょく きつ けん やしな たいせん わた よろ てん おう", "d": "天、山の中に在るは大畜なり。君子以て多く前言往行を識して、以て其德を畜ふ。", "rd": "てん やま なか あ たい ちく くんし もっ おお ぜん げん おう こう しる もっ その とく やしな", "y": [["厲き有り。已むに利し。", "厲き有り、已むに利しとは、災を犯さざるなり。"], ["輿、輹を説く。", "輿、輹を説くとは、中にして尤无きなり。"], ["良馬逐ふ。艱貞に利し。曰に（日々に）輿衞を閑ふ。往く攸有るに利し。", "往く攸有るに利しとは、上、志を合はするなり。"], ["童牛の牿なり。元吉。", "六四元吉とは、喜び有るなり。"], ["豶豕の牙なり。吉。", "六五の吉は、慶有るなり。"], ["天の衢を何ふ。亨る。", "天の衢を何ふとは、道大いに行はるるなり。"]], "ry": [["あやう あ や よろ", "あやう あ や よろ わざわい おか"], ["くるま とこばしり と", "くるま とこばしり と ちゅう とが な"], ["りょう ば お かんてい よろ ここ ひ び しゃ えい なら ゆ ところ あ よろ", "ゆ ところ あ よろ かみ こころざし あ"], ["どうぎゅう こく げんきつ", "りく し げん きつ よろこ あ"], ["ふん し が きつ", "りくご きつ よろこび あ"], ["てん ちまた にな とお", "てん ちまた にな みち おお おこな"]]}, "27": {"k": "頤は、貞にして吉。頤を觀、自ら口實を求む。", "rk": "い てい きつ い み みずか こう じつ もと", "t": "頤は貞にして吉とは、養ふこと正しければ則ち吉なるなり。頤を觀るとは、其の養ふ所を觀るなり。自ら口實を求むとは、其の自ら養ふを觀るなり。天地、萬物を養ひ、聖人、賢を養ひ、以て萬民に及ぼす。頤の時大なるかな。", "rt": "い てい きつ やしな ただ すなわ きつ い み そ やしな ところ み みずか こう じつ もと そ みずか やしな み てん ち ばんぶつ やしな せいじん けん やしな もっ ばんみん およ い ときおおい", "d": "山の下に雷有るは頤なり。君子以て言語を愼み、飲食を節す。", "rd": "やま した らい あ い くんし もっ げん ご つつし いんしょく せっ", "y": [["爾の霊亀を舍て、我を觀て頤を朶る。凶。", "我を觀て頤を朶るとは、亦、貴ぶに足らざるなり。"], ["顛に頤はる。經に拂る。丘に于て頤はれんとし、征けば凶。", "六二の征けば凶とは、行けば類を失ふなり。"], ["頤に拂る。貞なれども凶。十年、用ふる勿れ。利しき攸无し。", "十年、用ふ勿れとは、道大いに悖ればなり。"], ["顛に頤はる。吉。虎視眈眈たり。其欲遂遂たり。咎无し。", "顛に頤はるるの吉は、上の施し光なるなり。"], ["經に拂る。貞に居れば吉。大川を渉る可からず。", "貞に居るの吉は、順にして以て上に從へばなり。"], ["由りて頤はる。厲けれども吉。大川を渉るに利し。", "由りて頤はる、厲けれども吉とは、大いに慶有るなり。"]], "ry": [["なんじ れい き す われ み おとがい た きょう", "われ み おとがい た また たつと た"], ["さかさま やしな つね もと おか おい やしな ゆ きょう", "りくじ ゆ きょう ゆ るい うしな"], ["やしない もと てい きょう じゅうねん もち なか よろ ところ な", "じゅうねん もち なか みち おお もと"], ["さかさま やしな きつ こ し たん たん その よく ちく ちく とが な", "さかさま やしな きつ かみ ほどこ おおい"], ["つね もと てい お きつ たいせん わた べ", "てい お きつ じゅん もっ かみ したが"], ["よ やしな あやう きつ たいせん わた よろ", "よ やしな あやう きつ おお よろこびあ"]]}, "28": {"k": "大過は、棟橈む。往く攸有るに利し。亨る。", "rk": "たいか むなぎたわ ゆ ところ あ よろ とお", "t": "大過は、大なる者過ぐるなり。棟撓むとは、本末弱ければなり。剛過ぎたれども中し、巽にして説びて行く。往く攸有るに利し。乃ち亨る。大過の時は大なるかな。", "rt": "たい か だい もの す むなぎたわ ほんまつ よわ ごう す ちゅう そん よろこ ゆ ゆ ところ あ よろ すなわ とお たいか とき おおい", "d": "澤、木を滅するは、大過なり。君子以て獨立して懼れず、世を遯れて悶ゆる无し。", "rd": "さわ き めっ たい か くんし もっ どく りつ おそ よ のが もだ な", "y": [["藉くに白茅を用ふ。咎无し。", "藉くに白茅を用ふとは、柔、下に在るなり。"], ["枯楊、稊を生ず。老夫、其女妻を得。利しからざる无し。", "老夫女妻は、過ぎて以て相與するなり。"], ["棟橈む。凶。", "棟橈むの凶は、以て輔有る可からざるなり。"], ["棟隆し。吉。它有れば吝。", "棟隆きの吉は、下に撓まざるなり。"], ["枯楊、華を生ず。老婦、其士夫を得。咎も无く譽も无し。", "枯楊、華を生ずるは、何ぞ久しかる可けんや。老婦士夫は、亦、醜とす可きなり。"], ["過ぎて渉りて頂を滅す。凶。咎无し。", "過ぎて渉るの凶は、咎む可からざるなり。"]], "ry": [["し はく ぼう もち とが な", "し はく ぼう もち じゅう しも あ"], ["こ よう ひこばえ しょう ろう ふ その じょ さい う よろ な", "ろう ふ じょ さい す もっ あい くみ"], ["むなぎたわ きょう", "むなぎたわ きょう もっ たすけ あ べ"], ["むなぎたか きつ た あ りん", "むなぎたか きつ した たわ"], ["こ よう はな しょう ろう ふ その し ふ う とが な ほまれ な", "こ よう はな しょう なん ひさ べ ろう ふ し ふ また しゅう べ"], ["す わた いただき めっ きょう とが な", "す わた きょう とが べ"]]}, "29": {"k": "習坎は、孚有り。維れ心亨る。行きて尚ばるる有り。", "rk": "しゅうかん まこと あ こ こころとお ゆ たつと あ", "t": "習坎は重險なり。水は流れて盈たず、險を行きて其信を失はず。維れ心亨るとは、乃ち剛中を以てなり。行きて尚ばるる有りとは、往きて功有るなり。天險は升る可からざるなり。地險は山川丘陵なり。王公、險を設け、以て其國を守る。險の時用大なるかな。", "rt": "しゅうかん ちょうけん みず なが み けん ゆ その しん うしな こ こころとお すなわ ごうちゅう もっ ゆ たつと あ ゆ こう あ てん けん のぼ べ ち けん さんせんきゅうりょう おう こう けん もう もっ その くに まも けん とき よう おおい", "d": "水洊に至るは習坎なり。君子以て德行を常にし、教事を習ぬ。", "rd": "みずしきり いた しゅうかん くんし もっ とく こう つね きょう じ かさ", "y": [["習坎、坎窞に入る。凶。", "習坎、坎に入る、道を失ひて凶なるなり。"], ["坎に險有り。求め小しく得。", "求め小しく得とは、未だ中を出でざるなり。"], ["來るも之くも坎坎たり。險にして且つ枕す。坎窞に入る。用ふる勿れ。", "來るも之くも坎坎たりとは、終に功无きなり。"], ["樽酒、簋貳ふ。缶を用ふ。約を納るること牖よりす。終に咎无し。", "樽酒簋貳ふとは、剛柔際はるなり。"], ["坎、盈たず。祇に既く平らぐ。咎无し。", "坎、盈たずとは、中未だ大ならざるなり。"], ["係ぐに徽纆を用ひ、叢棘に寘く。三歳まで得ず。凶。", "上六は道を失ふ、凶なること三歳なり。"]], "ry": [["しゅうかん かんたん い きょう", "しゅうかん かん い みち うしな きょう"], ["かん けん あ もと すこ う", "もと すこ う いま うち い"], ["きた ゆ かんかん けん か まくら かんたん い もち なか", "きた ゆ かんかん つい こう な"], ["そんしゅ き そ ほとぎ もち やく おさま ゆう つい とが な", "そんしゅ き そ ごうじゅう まじ"], ["かん み まさ ことごと たい とが な", "かん み ちゅう いま おおい"], ["つな き ぼく もち そうきゃく お さんさい え きょう", "じょうりく みち うしな きょう さんさい"]]}, "30": {"k": "離は、貞しきに利し。亨る。牝牛を畜へば吉。", "rk": "り ただ よろ とお ひんぎゅう やしな きつ", "t": "離は麗くなり。日月は天に麗く。百穀草木は土に麗く。重明にして以て正に麗く。乃ち天下を化成す。柔、中正に麗く、故に亨る。是を以て牝牛を畜へば吉なるなり。", "rt": "り つ じつげつ てん つ ひゃっこく そう もく つち つ ちょうめい もっ まさ つ すなわ てんか かせい じゅう ちゅうせい つ ゆえ とお ここ もっ ひんぎゅう やしな きつ", "d": "明兩たび作るは離なり。大人以て明を繼ぎて四方を照らす。", "rd": "めい ふた おこ り たいじん もっ めい つ し ほう て", "y": [["履むこと錯然たり。之を敬すれば咎无し。", "履むこと錯はるの敬は、以て咎を辟くるなり。"], ["黄離なり。元吉。", "黄離元吉とは、中道を得ればなり。"], ["日昃くの離なり。缶を鼓して歌はざれば、則ち大耋を之れ嗟く。凶。", "日昃くの離は、何ぞ久しかる可けんや。"], ["突如として其れ来如たり。焚如たり、死如たり、棄如たり。", "突如として其れ來如たりとは、容るる處无きなり。"], ["涕を出すこと沱若たり。戚へて嗟若たり。吉。", "六五の吉は、王公に離けばなり。"], ["王用って出でて征す。嘉有り。首を折る。獲ること其醜に匪ず。咎无し。", "王用って出でて征すとは、以て邦を正すなり。"]], "ry": [["ふ さく ぜん これ けい とが な", "ふ まじ けい もっ とが さ"], ["こう り げんきつ", "こう どう げん きつ ちゅう どう う"], ["ひ かたむ り ほとぎ こ うた すなわ だいてつ こ なげ きょう", "ひ かたむ り なん ひさ べ"], ["とつじょ そ らいじょ ふん じょ し じょ き じょ", "とつじょ そ らいじょ い ところ な"], ["なみだ だ た じゃく うれ さ じゃく きつ", "りくご きつ おう こう つ"], ["おう もっ い せい か あ かしら お う そのたぐい あら とが な", "おう もっ い せい もっ くに ただ"]]}, "31": {"k": "咸は亨る。貞しきに利し。女を取れば吉。", "rk": "かん とお ただ よろ じょ めと きつ", "t": "彖に日く、咸とは感ずるなり。柔上りて剛下り、二氣感應して以て相與し、止まりて説び、男、女に下る。是を以て亨り、貞しきに利しく、女を取ればに吉なるなり。天地感じて万物化生し、聖人、人心を感じて、天下和平なり。其の感ずる所を觀て、天地萬物の情、見る可し。", "rt": "たん いわ かん かん じゅうのぼ ごう くだ に き かん のう もっ あい くみ とど よろこ だん じょ くだ ここ もっ とお ただ よろ じょ めと きつ てん ち かん ばんぶつ かせい せいじん じん しん かん てん か わ へい そ かん ところ み てんち ばんぶつ じょう み べ", "d": "山の上に澤有るは咸なり。君子以て虚にして人を受く。", "rd": "やま うえ たく あ かん くんし もっ きょ ひと う", "y": [["其拇に咸ず。", "其拇に咸ずとは、志、外に在るなり。"], ["其腓に咸ず。凶。居れば吉。", "凶なりと雖も居れば吉とは、順なれば害あらざるなり。"], ["其股に咸ず。其の隨ふを執る。往けば吝。", "其股に咸ずとは、亦、處らざるなり。志、人に隨ふに在り、執る所下なるなり。"], ["貞しければ吉にして悔亡ぶ。憧憧として往來すれば、朋、爾の思に從ふ。", "貞しければ吉にして悔亡ぶとは、未だ感の害あらざるなり。憧憧として往來するは、未だ光大ならざるなり。"], ["其脢に咸ず。悔无し。", "其脢に咸ずとは、志末なるなり。"], ["其輔頬舌に咸ず。", "其輔頬舌に咸ずとは、口説を滕ぐるなり。"]], "ry": [["そのぼ かん", "そのぼ かん こころざし そと あ"], ["そのこむら かん きょう お きつ", "きょう いえど お きつ じゅん がい"], ["その もも かん そ したが と ゆ りん", "そのもも かん また お こころざし ひと したが あ と ところ しも"], ["ただ きつ くい ほろ しょうしょう おう らい とも なんじ おもい したが", "ただ きつ くい ほろ いま かん がい しょうしょう おう らい いま こう だい"], ["そのせじし かん くい な", "そのせじし かん こころざしすえ"], ["その ほ きょうぜつ かん", "その ほ きょうぜつ かん こう ぜつ あ"]]}, "32": {"k": "恆は亨る。咎无し。貞しきに利し。往く攸有るに利し。", "rk": "こう とお とが な ただ よろ ゆ ところ あ よろ", "t": "恆は久しきなり。剛上りて柔下り、雷風相與し、巽にして動き、剛柔皆應ずるは、恆なり。恆は亨る、咎无し、貞しきに利しとは、其道に久しければなり。天地の道は、恆久にして已まざるなり。往く攸有るに利しとは、終れば則ち始まる有るなり。日月は天を得て能く久しく照らし、四時は變化して能く久しく成し、聖人は其道に久しくして、天下化成す。其の恆にする所を觀て、天地萬物の情、見る可し。", "rt": "こう ひさ ごう のぼ じゅうくだ らいふう あいくみ そん うご ごうじゅう みなおう こう こう とお とが な ただ よろ そのみち ひさ てん ち みち こう きゅう や ゆ ところ あ よろ おわ すなわ はじ あ じつげつ てん え よ ひさ て しいじ へん か よ ひさ な せいじん そのみち ひさ てん か か せい そ つね ところ み てん ち ばん ぶつ じょう み べ", "d": "雷風は恆なり。君子以て立ちて方を易へず。", "rd": "らいふう こう くんし もっ た ほう か", "y": [["恆を浚くす。貞しけれど凶。利しき攸无し。", "恆を浚くするの凶は、始めて求むること深ければなり。"], ["悔亡ぶ。", "九二の悔亡ぶるは、能く中に久しければなり。"], ["其徳を恆にせず。或は之に羞を承む。貞しけれども吝。", "其徳を恆にせず、容るる所无きなり。"], ["田に禽无し。", "其位に非ざるに久しくす、安んぞ禽を得んや。"], ["其徳を恆にす。貞。婦人は吉。夫子は凶。", "婦人は貞にして吉とは、一に從って終ればなり。夫子は義を制す。婦に從ふは凶なるなり。"], ["恆を振ふ。凶。", "恆を振うて上に在り。大いに功无きなり。"]], "ry": [["つね ふか ただ きょう よろ ところ な", "つね ふか きょう はじ もと ふか"], ["くい ほろ", "きゅうじ くい ほろ よ ちゅう ひさ"], ["その とく つね あるい これ はじ すす ただ りん", "その とく つね い ところ な"], ["でん えもの な", "そのくらい あら ひさ いずく えもの え"], ["その とく つね てい ふ じん きつ ふうし きょう", "ふ じん てい きつ いつ したが おわ ふうし ぎ せい ふ したが きょう"], ["つね ふる きょう", "つね ふる かみ あ おお こう な"]]}, "33": {"k": "遯は亨る。小は貞しきに利し。", "rk": "とん とお しょう ただ よろ", "t": "遯は亨るとは、遯れて而して亨るなり。剛、位に當りて應じ、時と與に行ふなり。小は貞しきに利しとは、浸くにして長ずればなり。遯の時義大なるかな。", "rt": "とん とお のが しか とお ごう くらい あた おう とき とも おこな しょう ただ よろ ようや ちょう とん じ ぎ おおい", "d": "天の下に山有るは遯なり。君子以て小人を遠ざけ、惡まずして嚴にす。", "rd": "てん した やま あ とん くんし もっ しょうじん とお にく げん", "y": [["遯るるの尾なり。厲し。往く攸有るに用ふる勿れ。", "遯尾の厲きは、往かずんば何の災あらんや。"], ["之を執るに黄牛の革を用ふ。之を説くに勝ふる莫し。", "執るに黄牛を用ふるは、志を固くするなり。"], ["遯を繋ぐ。疾有り。厲し。臣妾を畜へば、吉。", "繋遯の厲きは、疾有りて憊るるなり。臣妾を畜へば吉とは、大事に可ならざるなり。"], ["好すれども遯る。君子は吉。小人は否ず。", "君子は好すれども遯る。小人は否ざるなり。"], ["嘉く遯る。貞にして吉。", "嘉く遯る、貞にして吉とは、以て志を正しくするなり。"], ["肥に遯る。（肥びて遯る）利しからざる无し。", "肥に遯る（肥びて遯る）、利しからざる无しとは、疑ふ所无きなり。"]], "ry": [["のが しりえ あやう ゆ ところ あ もち なか", "とん び あやう ゆ なん わざわい"], ["これ と こうぎゅう かわ もち これ と た な", "と こうぎゅう もち こころざし かた"], ["とん つな やまい あ あやう しんしょう やしな きつ", "けい とん あやう やまい あ つか しんしょう やしな きつ だい じ か"], ["よみ のが くんし きつ しょうじん しから", "くんし よみ のが しょうじん しから"], ["よ のが てい きつ", "よ のが てい きつ もっ こころざし ただ"], ["ゆたか のが と のが よろ な", "ゆたか のが と のが よろ な うたが ところ な"]]}, "34": {"k": "大壯は、貞しきに利し。", "rk": "たいそう ただ よろ", "t": "大壯とは、大なる者壯なるなり。剛にして以て動く、故に壯なり。大壯は貞しきに利しとは、大なる者正しきなり。正大にして、天地の情、見る可し。", "rt": "たいそう だい ものさかん ごう もっ うご ゆえ さかん たいそう ただ よろ だい もの ただ せい だい てん ち じょう み べ", "d": "雷、天の上に在るは、大壯なり。君子以て禮に非ざれば履まず。", "rd": "らい てん うえ あ たい そう くんし もっ れい あら ふ", "y": [["趾に壯なり。征けば凶。孚有り。", "趾に壯なりとは、其孚窮するなり。"], ["貞にして吉。", "九二の貞にして吉なるは、中なるを以てなり。"], ["小人は壯を用ふ。君子は罔を用ふ。貞なれども厲し。羝羊、藩に觸れ、其角を羸む。", "小人は壯を用ふ。君子は罔きなり。"], ["貞にして吉、悔亡ぶ。藩決して羸まず。大輿の輹に壯なり。", "藩決して羸まずとは、往くを尚ぶなり。"], ["羊を易に喪ふ。悔无し。", "羊を易に喪ふとは、位、當らざればなり。"], ["羝羊、藩に觸れ、退く能はず、遂ぐる能はず。利しき攸无し。艱めば則ち吉。", "退く能はず、遂ぐる能はずとは、詳かならざるなり。艱めば則ち吉とは咎、長からざるなり。"]], "ry": [["あし さかん ゆ きょう まこと あ", "あし さかん そのまこときゅう"], ["てい きつ", "きゅうじ てい きつ ちゅう もっ"], ["しょうじん そう もち くんし もう もち てい あやう てい よう まがき ふ そのつの くるし", "しょうじん そう もち くんし な"], ["てい きつ くいほろ まがきけっ くるし たい よ とこばしり さかん", "まがきけっ くるし ゆ たつと"], ["ひつじ さかい うしな くい な", "ひつじ さかい うしな くらい あた"], ["ていよう まがき ふ しりぞ あた と あた よろ ところ な なや すなわ きつ", "しりぞ あた と あた つまびら なや すなわ きつ とが なが"]]}, "35": {"k": "晉は、康侯用って馬を錫ること藩庶なり。晝日に三たび接す。", "rk": "しん こう こう も うま たてまつ はん しょ ちゅうじつ み せっ", "t": "晉は、進むなり。明、地の上に出で、順にして大明に麗き、柔進みて上り行く。是を以て、康侯用って馬を錫ること藩庶にして、晝日に三たび接するなり。", "rt": "しん すす めい ち うえ い じゅん たいめい つ じゅうすす のぼ ゆ ここ もっ こう こう も うま たてまつ はんしょ ちゅうじつ み せっ", "d": "明、地の上に出づるは、晉なり。君子以て自ら明德を昭かにす。", "rd": "めい ち うえ い しん くんし もっ みずか めい とく あきら", "y": [["晉如たり摧如たり。貞にして吉。孚とする罔し。裕なれば咎无し。", "晉如たり摧如たりとは、獨り正を行へばなり。裕なれば咎无しとは、未だ命を受けざればなり。"], ["晉如たり愁如たり。貞にして吉。玆の介福を其王母に受く。", "玆の介福を受くとは、中正なるを以てなり。"], ["衆允とす。悔亡ぶ。", "衆、之を允とす。志上り行くなり。"], ["晉如たり、鼫鼠なり。貞なれども厲し。", "鼫鼠、貞なれども厲しとは、位當らざればなり。"], ["悔亡ぶ。失得、恤ふる勿れ。往けば吉、利しからざる无し。", "失得、恤ふる勿れとは、往きて慶有るなり。"], ["其角に晉む。維れ用って邑を伐つ。厲けれども吉にして咎无し。貞なれども吝。", "維れ用って邑を伐つとは、道未だ光ならざるなり。"]], "ry": [["しん じょ さい じょ てい きつ まこと な ゆたか とが な", "しん じょ さい じょ ひと せい おこな ゆたか とが な いま めい う"], ["しんじょ しゅうじょ てい きつ こ かいふく その おう ぼ", "こ かいふく う ちゅうせい もっ"], ["しゅうまこと くい ほろ", "しゅう これ まこと こころざしのぼ ゆ"], ["しんじょ せき そ てい あやう", "せき そ てい あやう くらいあた"], ["くいほろ しっとく うれ なか ゆ きつ よろ な", "しっとく うれ なか ゆ よろこびあ"], ["そのつの すす こ も ゆう う あやう きつ とが な てい りん", "こ も ゆう う みち いま おおい"]]}, "36": {"k": "明夷は、艱貞に利し。", "rk": "めいい かんてい よろ", "t": "明、地中に入るは明夷なり。内は文明にして外は柔順、以て大難を蒙る。文王、之を以ふ。艱貞に利しとは、其明を晦ますなり。内難にして而も能く其志を正しくす。箕子、之を以ふ。", "rt": "めい ち ちゅう い めいい うち ぶんめい そと じゅうじゅん もっ たいなん こうむ ぶんのう これ もち かんてい よろ そのめい くら うち なん しか よ そのこころざし ただ き し これ もち", "d": "明、地の中に入るは、明夷なり。君子以て衆に涖むに、晦きを用ひて明かなり。", "rd": "めい ち なか い めい い くんし もっ しゅう のぞ くら もち あきら", "y": [["明夷る。于き飛び、其翼を垂る。君子于き行く。三日、食はず。往く攸有り。主人、言有り。", "君子于き行くとは、義、食はざるなり。"], ["明夷る。左股を夷る。用って拯ふに馬壯なれば吉。", "六二の吉なるは、順にして以て則あればなり。"], ["明夷る。于きて南に狩す。其大首を得。疾くす可からず。貞。", "南に狩するの志、乃ち大いに得るなり。"], ["左腹に入る。明夷の心を獲たり。于きて門庭を出づ。", "左腹に入るとは、心意を獲るなり。"], ["箕子の明夷なり。貞に利し。", "箕子の貞は、明、息む可からざるなり。"], ["明かならずして晦し。初めには天に登り、後には地に入る。", "初めは天に登るとは、四國を照らすなり。後には地に入るとは、則を失ふなり。"]], "ry": [["めいやぶ ゆ と そのつばさ た くん し ゆ ゆ みっか くら ゆ ところ あ しゅじん げん あ", "くんし ゆ ゆ ぎ くら"], ["めいやぶ さ こ やぶ も すく うまさかん きつ", "りくじ きつ じゅん もっ のり"], ["めいやぶ ゆ みなみ かり その たい しゅ う と べ てい", "みなみ かり こころざし すなわ おお う"], ["さふく い めいい こころ え ゆ もんてい い", "さふく い しん い う"], ["き し めいい てい よろ", "き し てい めい や べ"], ["あきら くら はじ てん のぼ のち ち い", "はじ てん のぼ し こく て のち ち い のり うしな"]]}, "37": {"k": "家人は、女の貞しきに利し。", "rk": "かじん おんな ただ よろ", "t": "家人は、女、位を内に正しくし、男、位を外に正しくす。男女正しきは、天地の大義なり。家人には嚴君あり。父母の謂なり。父は父たり子は子たり、兄は兄たり弟は弟たり、夫は夫たり婦は婦たり、而して家道正し。家を正しくして天下定まる。", "rt": "かじん おんな くらい うち ただ おとこ くらい そと ただ だんじょ ただ てん ち たいぎ かじん げんくん ふ ぼ いい ちち ちち こ こ あに あに おとうと おとうと おっと おっと つま つま しか かどう ただ いえ ただ てんか さだ", "d": "風、火より出づるは家人なり。君子以て言、物有り、而して行、恆有り。", "rd": "かぜ ひ い かじん くんし もっ げん もの あ しか おこない つね あ", "y": [["有家を閑ぐ。悔亡ぶ。", "有家を閑ぐとは、志未だ變ぜざるなり。"], ["遂ぐる攸无し。中饋に在り。貞にして吉。", "六二の吉は、順にして以て巽なればなり。"], ["家人嗃嗃たり。悔い厲けれども吉。婦子嘻嘻たり。終に吝。", "家人嗃嗃たりとは、未だ失はざるなり。婦子嘻嘻たりとは、家節を失ふなり。"], ["家を富ます。大吉。", "家を富ます、大吉とは、順にして位に在るなり。"], ["王、有家に假る。恤うる勿れ。吉。", "王、有家に假るとは、交々相愛するなり。"], ["孚有り威如たり。終に吉。", "威如の吉とは、身に反るの謂なり。"]], "ry": [["ゆうか ふせ くい ほろ", "ゆうか ふせ こころざしいま へん"], ["と ところ な ちゅう き あ てい きつ", "りくじ きつ じゅん もっ そん"], ["かじん かく かく く あやう きつ ふ し き き つい りん", "かじん かく かく いま うしな ふ し き き か せつ うしな"], ["いえ と だいきつ", "いえ と だいきつ じゅん くらい あ"], ["おう ゆう か いた うれ なか きつ", "おう ゆう か いた こも ごも あい あい"], ["まこと あ い じょ つい きつ", "い じょ きつ み かえ いい"]]}, "38": {"k": "睽は、小事は吉。", "rk": "けい しょう じ きつ", "t": "睽は、火動きて上り、澤動きて下る。二女同じく居り、其志、行を同じくせず。説びて明に麗き、柔進みて上り行き、中を得て剛に應ず。是を以て小事は吉なり。天地睽きて其事同じきなり。男女睽きて其志通ずるなり。萬物睽きて其事類するなり。睽の時用大なるかな。", "rt": "けい ひ うご のぼ さわ うご くだ にじょ おな お そのこころざしおこない おな よろこ めい つ じゅうすす のぼ ゆ ちゅう え ごう おう ここ もっ しょうじ きつ てんち そむ その こと おな だん じょ そむ そのこころざしつう ばんぶつそむ その こと るい けい とき よう おおい", "d": "上は火下は澤なるは、睽なり。君子以て同じくして異なり。", "rd": "うえ ひ した たく けい くんし もっ おな ことなる", "y": [["悔亡ぶ。馬を喪ふ。逐ふ勿れ。自ら復る。惡人を見れば咎无し。", "惡人を見るは、以て咎を辟くるなり。"], ["主に巷に遇ふ。咎无し。", "主に巷に遇ふは、未だ道を失はざるなり。"], ["輿の曳かるるを見るに、其牛は掣、其人は天且つ劓。初め无くして終り有り。", "輿の曳かるるを見るとは、位當らざればなり。初め无くして終り有りとは、剛に遇へばなり。"], ["睽孤なり。元夫に遇ひ、交々孚あり。厲けれども咎无し。", "交々孚あり咎无しとは、志、行はるるなり。"], ["悔亡ぶ。厥宗、膚を噬む。往きて何の咎あらん。", "厥宗、膚を噬むとは、往きて慶有るなり。"], ["睽孤なり。豕が塗を負ひ、鬼を載すること一車なるを見る。先には之が弧を張り、後には之が弧を説く。寇に匪ず婚媾なり。往きて雨に遇へば則ち吉。", "雨に遇ふの吉は、群疑亡ぶればなり。"]], "ry": [["くい ほろ うま うしな お なか おのずか かえ あくにん み とが な", "あくにん み もっ とが さ"], ["しゅ ちまた あ とが な", "しゅ ちまた あ いま みち うしな"], ["くるま ひ み その うし せい その ひと てん か ぎ はじ な おわ あ", "くるま ひ み くらいあた はじ な おわ あ ごう あ"], ["けい こ げん ぷ あ こも ごも まこと あやう とが な", "こも ごも まこと とが な こころざし おこな"], ["くい ほろ その そう ふ か ゆ なん とが", "その そう ふ か ゆ よろこびあ"], ["けい こ いのこ どろ お き の いちしゃ み さき これ ゆみ は のち これ ゆみ と あだ あら こん こう ゆ あめ あ すなわ きつ", "あめ あ きつ ぐん ぎ ほろ"]]}, "39": {"k": "蹇は、西南に利しく、東北に利しからず。大人を見るに利し。貞にして吉。", "rk": "けん せい なん よろ とうほく よろ たいじん み よろ てい きつ", "t": "蹇は難なり。險、前に在るなり。險を見て能く止まるは、知なるかな。蹇は西南に利しとは、往きて中を得るなり。東北に利しからずとは、その道窮するなり。大人を見るに利しとは、往きて功あるなり。位に當り貞にして吉とは、以て邦を正しくするなり。蹇の時用大なるかな。", "rt": "けん なん けん まえ あ けん み よ とど ち けん せいなん よろ ゆ ちゅう う とう ほく よろ みちきゅう たいじん み よろ ゆ こう くらい あた てい きつ もっ くに ただ けん とき よう おおい", "d": "山の上に水有るは蹇なり。君子以て身に反りて徳を修む。", "rd": "やま うえ みず あ けん くんし もっ み かえ とく おさ", "y": [["往けば蹇み、來れば譽あり。", "往けば蹇み來れば譽ありとは、宜しく待つべきなり。"], ["王臣蹇蹇たり。躬の故に匪ず。", "王臣蹇蹇たるは、終に尤无きなり。"], ["往けば蹇み、來れば反る。", "往けば蹇み、來れば反るとは、内、之を喜ぶなり。"], ["往けば蹇み、來れば連なる。", "往けば蹇み來れば連なるとは、位に當りて實なればなり。"], ["大蹇なり。朋來る。", "大蹇なり、朋來るとは、中節を以てなり。"], ["往けば蹇み、來れば碩なり。吉。大人を見るに利し。", "往けば蹇み來れば碩なりとは、志、内に在るなり。大人を見るに利しとは、以て貴きに從ふなり。"]], "ry": [["ゆ なや きた ほまれ", "ゆ なや きた ほまれ よろ ま"], ["おう しん けん けん み ゆえ あら", "おう しん けん けん つい とが な"], ["ゆ なや きた かえ", "ゆ なや きた かえ うち これ よろこ"], ["ゆ なや きた つら", "ゆ なや きた つら くらい あた じつ"], ["たいけん とも きた", "たいけん とも きた ちゅうせつ もっ"], ["ゆ なや きた おおい きつ たいじん み よろ", "ゆ なや きた おおい こころざし うち あ たいじん み よろ もっ たつと したが"]]}, "40": {"k": "解は、西南に利し。往く攸无ければ、其れ來り復りて吉。往く攸有れば、夙くして吉。", "rk": "かい せいなん よろ ゆ ところ な そ きた かえ きつ ゆ ところ あ はや きつ", "t": "解は、險にして以て動き、動きて險を免るるは解なり。解は西南に利しとは、往きて衆を得るなり。其れ來り復りて吉とは、乃ち中を得るなり。往く攸有れば夙くして吉とは、往きて功有るなり。天地解けて雷雨作り、雷雨作りて百果草木皆甲坼す。解の時大なるかな。", "rt": "かい けん もっ うご うご けん まぬが かい かい せい なん よろ ゆ しゅう う そ きた かえ きつ すなわ ちゅう う ゆ ところ あ はや きつ ゆ こう あ てん ち と らい う おこ らい う おこ ひゃっか そうもく みな こう たく かい ときおおい", "d": "雷雨作るは解なり。君子以て過を赦し罪を宥む。", "rd": "らい う おこ かい くんし もっ あやまち ゆる つみ なだ", "y": [["咎无し。", "剛柔の際、義、咎无きなり。"], ["田して三狐を獲、黄矢を得たり。貞にして吉。", "九二の貞にして吉なるは、中道を得ればなり。"], ["負うて且つ乘る。寇の至るを致す。貞なれども吝。", "負うて且つ乘るとは、亦、醜とす可きなり。我より寇を致す、又誰を咎めんや。"], ["而の拇を解け。朋至りて斯れ孚とせん。", "而の拇を解けとは、未だ位に當らざればなり。"], ["君子維れ解く有り。吉。小人に孚有り。", "君子、解く有りとは、小人退くなり。"], ["公用って隼を高墉の上に射る。之を獲て利しからざる无し。", "公用って隼を射るとは、以て悖れるを解くなり。"]], "ry": [["とが な", "ごうじゅう まじわり ぎ とが な"], ["かり さん こ え こう し え てい きつ", "きゅうじ てい きつ ちゅうどう う"], ["お か の あだ いた いた てい りん", "お か の また しゅう べ われ あだ いた まただれ とが"], ["なんじ ぼ と とも いた こ まこと", "なんじ ぼ と いま くらい あた"], ["くんし こ と あ きつ しょうじん まこと あ", "くんし と あ しょうじん しりぞ"], ["こう も はやぶさ こう よう うえ い これ え よろ な", "こう も はやぶさ い もっ もと と"]]}, "41": {"k": "損は、孚有り。元吉。咎无し。貞にす可し。往く攸有るに利し。曷をか之れ用ひん。二簋、用って享す可し。", "rk": "そん まこと あ げんきつ とが な てい べ ゆ ところ あ よろ なに こ もち に き も とお べ", "t": "損は、下を損して上を益し、其道上り行く。損して孚有り。元吉。咎无し。貞にす可し。往く攸有るに利し。曷をか之れ用ひん。二簋、用って享す可し。二簋は應に時有るべし。剛を損して柔を益すには時有り。損益盈虚、時と偕に行ふ。", "rt": "そん しも そん かみ ま そのみち のぼ ゆ そん まこと あ げんきつ とが な てい べ ゆ ところ あ よろ なに こ もち に き も とお べ に き まさ とき あ ごう そん じゅう ま とき あ そんえき えいきょ とき とも おこな", "d": "山の下に澤有るは損なり。君子以て忿を懲らし欲を窒ぐ。", "rd": "やま した たく あ そん くんし もっ いかり こ よく ふさ", "y": [["事を已めて遄かに往く。咎无し。酌みて之を損す。", "事を已めて遄かに往くとは、尚、志を合はするなり。"], ["貞に利し。征くは凶。損せずして之を益す。", "九二、貞に利しとは、中以て志と為すなり。"], ["三人行けば、則ち一人を損す。一人行けば則ち其友を得。", "一人行くとは、三なれば則ち疑ふなり。"], ["其疾を損す。遄かならしむれば喜有り。咎无し。", "其疾を損すとは、亦、喜ぶ可きなり。"], ["或は之を益す。十朋の龜も違ふ克はず。元吉。", "六五の元吉は、上より祐くるなり。"], ["損せずして之を益す。咎无し。貞にして吉。往く攸有るに利し。臣を得て家无し。", "損せずして之を益すとは、大いに志を得るなり。"]], "ry": [["こと や すみや ゆ とが な く これ へら", "こと や すみや ゆ かみ こころざし あ"], ["てい よろ ゆ きょう そん これ ま", "きゅうじ てい よろ ちゅうもっ こころざし な"], ["さんにん ゆ すなわ いちにん そん いちにん ゆ すなわ そのとも う", "いちにん ゆ さん すなわ うたが"], ["そのやまい そん すみや よろこびあ とが な", "そのやまい そん また よろこ べ"], ["あるい これ ま じっぽう き たが あた げんきつ", "りくご げんきつ かみ たす"], ["そん これ ま とが な てい きつ ゆ ところ あ よろ しん え いえ な", "そん これ ま おお こころざし う"]]}, "42": {"k": "益は、往く攸有るに利し。大川を渉るに利し。", "rk": "えき ゆ ところ あ よろ たいせん わた よろ", "t": "益は上を損して下を益し、民説ぶこと疆无し。上より下に下り、其道大いに光る。往く攸有るに利しとは、中正にして慶有るなり。大川を渉るに利しとは、木道乃ち行はるるなり。益は動きて巽ひ、日に進むこと疆无し。天施し地生じ、其益、方无し。凡そ益の道は、時と偕に行はる。", "rt": "えき かみ そん しも ま たみよろこ かぎりな かみ しも くだ そのみちおお ひか ゆ ところあ よろ ちゅうせい よろこびあ たいせん わた よろ もくどう すなわ おこな えき うご したが ひ すす かぎり な てんほどこ ち しょう そのえき ほう な およ えき みち とき とも おこな", "d": "風雷は益なり。君子以て善を見れば則ち遷り、過有れば則ち改む。", "rd": "ふう らい えき くんし もっ ぜん み すなわ うつ あやまちあ すなわ あらた", "y": [["用って大作を爲すに利し。元吉。咎无し。", "元吉、咎无しとは、下、事を厚くせざるなり。"], ["或は之を益す。十朋の龜も違ふ克はず。永貞にして吉。王用って帝に亨す。吉。", "或は之を益すとは、外より來るなり。"], ["之を益すに凶事を用ふ。咎无し。孚有り中行あり。公に告ぐるに圭を用ふ。", "益すに凶事を用うるは、固より之を有するなり。"], ["中行ありて公に告げて從はる。用って依を爲し國を遷すに利し。", "公に告げて從はるるとは、益の志を以てなり。"], ["孚有り惠心あり。問ふ勿くして元吉。孚有り我が徳を惠とす。", "孚有り惠心あるは、之を問ふ勿し。我が徳を惠とするは、大いに志を得るなり。"], ["之を益す莫し。或は之を撃つ。心を立つること恆勿し、凶。", "之を益す莫しとは、偏辭なり。或は之を撃つとは、外より來るなり。"]], "ry": [["も だい さく な よろ げんきつ とが な", "げんきつ とが な しも こと あつ"], ["あるい これ ま じっぽう き たが あた えいてい きつ おう も てい きょう きつ", "あるい これ ま ほか きた"], ["これ ま きょうじ もち とが な まこと あ ちゅうこう こう つ けい もち", "ま きょうじ もち もと これ ゆう"], ["ちゅうこう こう つ したが も い な くに うつ よろ", "こう つ したが えき こころざし もっ"], ["まこと あ けいしん と な げんきつ まこと あ わ とく めぐみ", "まこと あ けいしん これ と な わ とく めぐみ おお こころざし う"], ["これ ま な あるい これ う こころ た つね な きょう", "これ ま な へん じ あるい これ う ほか きた"]]}, "43": {"k": "夬は、王庭に揚ぐ。孚ありて號ぶ。厲き有り。告ぐること邑よりす。戎に即くに利しからず。往く攸有るに利し。", "rk": "かい おう てい あ まこと さけ あやう あ つ ゆう じゅう つ よろ ゆ ところ あ よろ", "t": "夬は、決するなり。剛、柔を決するなり。健にして説び、決して和ぐ。王庭に揚ぐるは、柔、五剛に乘ずればなり。孚ありて號ぶ、厲き有りとは、其れ危ぶめば乃ち光いなるなり。邑より告ぐ、戎に即くに利しからずとは、尚ぶ所乃ち窮すればなり。往く攸有るに利しとは、剛長ずれば乃ち終ればなり。", "rt": "かい けっ ごう じゅう けっ けん よろこ けっ やわら おうてい あ じゅう ご ごう じょう まこと さけ あやう あ そ あや すなわ おおい ゆう つ じゅう つ よろ たつと ところすなわ きゅう ゆ ところ あ よろ ごうちょう すなわ おわ", "d": "澤、天に上るは夬なり。君子以て祿を施して下に及ぶ。德を居くは則ち忌む。", "rd": "たく てん のぼ かい くんし もっ ろく ほどこ しも およ とく お すなわ い", "y": [["趾を前むるに壯なり。往きて勝たず。咎と為す。", "勝たずして往くは、咎なり。"], ["惕れて號ぶ。莫夜、戎有るも、恤ふる勿れ。", "戎有るも恤ふる勿れとは、中道を得ればなり。"], ["頄に壯なり。凶有り。君子は夬夬たり。獨り行きて雨に遇ひ、濡るるが若くにして慍らるる有れども、咎无し。", "君子は夬夬たりとは、終に咎无きなり。"], ["臀に膚无し。其の行くこと次且たり。羊を牽けば悔亡ぶ。言を聞きて信ぜず。", "其の行くこと次且たりとは、位、當らざるなり。言を聞きて信ぜずとは、聽くこと明かならざるなり。"], ["莧陸、夬夬たり。中行にして咎无し。", "中行にして咎无しとは、中未だ光ならざるなり。"], ["號ぶ无かれ。終に凶有り。", "號ぶ无きの凶は、終に長かる可からざるなり。"]], "ry": [["あし すす さかん ゆ か とが な", "か ゆ とが"], ["おそ さけ ぼ や じゅう あ うれ なか", "じゅう あ うれ なか ちゅうどう う"], ["き さかん きょう あ くんし かいかい ひと ゆ あめ あ ぬ ごと いきどお あ とが な", "くんし かいかい つい とが な"], ["とん ふ な そ ゆ し しょ ひつじ ひ くい ほろ げん き しん", "そ ゆ し しょ くらい あた げん き しん き あきら"], ["けん りく かいかい ちゅうこう とが な", "ちゅうこう とが な ちゅういま おおい"], ["さけ な つい きょう あ", "さけ な きょう つい なが べ"]]}, "44": {"k": "姤は、女壯なり。女を取るに用ふる勿れ。", "rk": "こう おんなさかん おんな めと もち なか", "t": "姤は遇ふなり。柔、剛に遇ふなり。女を取るに用ふる勿れとは、與に長かる可からざればなり。天地相遇ひ、品物咸く章かなり。剛、中正に遇へば、天下大いに行はるるなり。姤の時義大なるかな。", "rt": "こう あ じゅう ごう あ おんな めと もち なか とも なが べ てん ち あい あ ひんぶつことごと あきら ごう ちゅうせい あ てん か おお おこな こう じ ぎ おおい", "d": "天の下に風有るは、姤なり、后以て命を施し四方に誥ぐ。", "rd": "てん した かぜ あ こう きみ もっ めい ほどこ し ほう つ", "y": [["金柅に繋ぐ。貞にして吉。往く攸有れば凶を見る。羸豕孚に蹢躅たり。", "金柅に繋ぐとは、柔道牽けばなり。"], ["包に魚有り。咎无し。賓に利しからず。", "包に魚有りとは、義、賓に及ばざるなり。"], ["臀に膚无し。其の行くこと次且たり。厲けれども大いなる咎无し。", "其の行くこと次且たりとは、行くこと未だ牽かれざるなり。"], ["包に魚无し。起てば凶。", "魚无きの凶は、民に遠ければなり。"], ["杞を以て瓜を包む。章を含む。天より隕つる有り。", "九五、章を含むは、中正なるなり。天より隕つる有りとは、志、命を舎てざるなり。"], ["其角に姤ふ。吝。咎无し。", "其角に姤ふとは、上窮まりて吝なるなり。"]], "ry": [["きん じ つな てい きつ ゆ ところ あ きょう み るい し まこと てきちょく", "きん じ つな じゅうどう ひ"], ["ほう うお あ とが な ひん よろ", "ほう うお あ ぎ ひん およ"], ["とん ふ な そ ゆ し しょ あやう おお とが な", "そ ゆ し しょ ゆ いま ひ"], ["ほう うお な た きょう", "うお な きょう たみ とお"], ["き もっ うり つつ あや ふく てん お あ", "きゅうご あや ふく ちゅうせい てん お あ こころざし めい す"], ["そのつの あ りん とが な", "そのつの あ かみきわ りん"]]}, "45": {"k": "萃は亨る。王、有廟に假る。大人を見るに利し。亨る。貞しきに利し。大牲を用ひて吉。往く攸有るに利し。", "rk": "すい とお おう ゆうびょう いた たいじん み よろ とお ただ よろ たいせい もち きつ ゆ ところ あ よろ", "t": "萃は聚まるなり。順にして以て説び、剛中にして應ず、故に聚まるなり。王、有廟に假るとは、孝享を致すなり。大人を見るに利し、亨るとは、聚まるに正を以てするなり。大牲を用ひて吉、往く攸有るに利しとは、天命に順ふなり。其の聚まる所を觀て、天地萬物の情、見る可し。", "rt": "すい あつ じゅん もっ よろこ ごうちゅう おう ゆえ あつ おう ゆうびょう いた こう きょう いた たいじん み よろ とお あつ せい もっ たいせい もち きつ ゆ ところ あ よろ てんめい したが そ あつ ところ み てん ち ばんぶつ じょう み べ", "d": "澤、地に上るは、萃なり。君子以て戎器を除め、不虞を戒む。", "rd": "たく ち のぼ すい くんし もっ じゅうき おさ ふ ぐ いまし", "y": [["孚有れども終へず、乃ち亂れ乃ち萃まる。若し號べば一握して笑と爲る。恤うる勿れ。往きて咎无し。", "乃ち亂れ乃ち萃まるとは、其志亂るるなり。"], ["引けば吉。咎无し。孚あり、乃ち禴を用ふるに利し。", "引けば吉、咎无しとは、中、未だ變ぜざるなり。"], ["萃如たり嗟如たり。利しき攸无し。往けば咎无し。小しく吝。", "往けば咎无しとは、上巽へばなり。"], ["大吉にして咎无し。", "大吉にして咎无しとは、位、當らざるなり。"], ["有位に萃まる。咎无し。孚とせられず。元永貞なれば、悔亡ぶ。", "有位に萃まるとは、志未だ光ならざるなり。"], ["齎咨涕洟す。咎无し。", "齎咨涕洟するは、未だ上に安んぜざるなり。"]], "ry": [["まこと あ お すなわ みだ すなわ あつ も さけ いちあく わらい な うれ なか ゆ とが な", "すなわ みだ すなわ あつ そのこころざしみだ"], ["ひ きつ とが な まこと すなわ やく もち よろ", "ひ きつ とが な ちゅう いま へん"], ["すいじょ さ じょ よろ ところ な ゆ とが な すこ りん", "ゆ とが な かみしたが"], ["だいきつ とが な", "だいきつ とが な くらい あた"], ["ゆう い あつ とが な まこと げんえいてい くい ほろ", "ゆう い あつ こころざしいま おおい"], ["せい し てい い とが な", "せい し てい い いま かみ やす"]]}, "46": {"k": "升は、元に亨る。用って大人を見る。恤ふる勿れ。南征して吉。", "rk": "しょう おおい とお も たいじん み うれ なか なんせい きつ", "t": "柔、時を以て升り、巽にして順、剛中にして應ず。是を以て大いに亨る。用って大人を見る、恤ふる勿れとは、慶有るなり。南征して吉とは、志行はるるなり。", "rt": "じゅう とき もっ のぼ そん じゅん ごうちゅう おう ここ もっ おお とお も たいじん み うれ なか よろこびあ なんせい きつ こころざしおこな", "d": "地の中に木を生ずるは、升なり。君子以て德に順ひ、小を積みて以て高大なり。", "rd": "ち なか き しょう しょう くんし もっ とく したが しょう つ もっ こうだい", "y": [["允に升る。大吉。", "允に升る、大吉とは、上、志を合はするなり。"], ["孚あり乃ち禴を用ふるに利し。咎无し。", "九二の孚は、喜び有るなり。"], ["虚邑に升る。", "虚邑に升るとは、疑ふ所无きなり。"], ["王用って岐山に亨す。吉にして咎无し。", "王用って岐山に亨すとは、順にして事ふるなり。"], ["貞にして吉。階に升る。", "貞にして吉、階に升るとは、大いに志を得るなり。"], ["冥くして升る。息まざるの貞に利し。", "冥くして升りて上に在り、消して富まざるなり。"]], "ry": [["まこと のぼ だいきつ", "まこと のぼ だいきつ かみ こころざし あ"], ["まこと すなわ やく もち よろ とが な", "きゅうじ まこと よろこ あ"], ["きょゆう のぼ", "きょゆう のぼ うたが ところ な"], ["おう も き ざん きょう きつ とが な", "おう も き ざん きょう じゅん つか"], ["てい きつ かい のぼ", "てい きつ かい のぼ おお こころざし う"], ["くら のぼ や てい よろ", "くら のぼ かみ あ け と"]]}, "47": {"k": "困は、亨る。貞し。大人は吉。咎无し。言ふ有れども信ぜられず。", "rk": "こん とお ただ たいじん きつ とが な い あ しん", "t": "困は、剛揜はるるなり。險にして以て説ぶ。困すれども其の亨る所を失はざるは、其れ唯だ君子か。貞、大人は吉とは、剛中なるを以てなり。言ふ有れども信ぜられずとは、口を尚べば乃ち窮するなり。", "rt": "こん ごうおお けん もっ よろこ こん そ とお ところ うしな そ た くんし てい たいじん きつ ごうちゅう もっ い あ しん くち たつと すなわ きゅう", "d": "澤に水无きは、困なり。君子以て命を致し志を遂ぐ。", "rd": "たく みず な こん くんし もっ めい いた こころざし と", "y": [["臀、株木に困しむ。幽谷に入る。三歳、觀ず。", "幽谷に入るとは、幽くして明かならざるなり。"], ["酒食に困しむ。朱紱方に來らんとす。用って亨祀するに利し。往くは凶。咎无し。", "酒食に困しむとは、中にして慶有るなり。"], ["石に困しみ、蒺藜に據る。其宮に入り、其妻を見ず。凶。", "蒺藜に據るとは、剛に乘るなり。其宮に入り、其妻を見ずとは、不祥なるなり。"], ["來ること徐徐たり。金車に困しむ。吝。終有り。", "來ること徐徐たりとは、志下に在るなり。位に當らずと雖も、與有るなり。"], ["劓刖す。赤紱に困しむ。乃ち徐ろに説有り。用って祭祀するに利し。", "劓刖すとは、志未だ得ざるなり。乃ち徐ろに説有りとは、中直なるを以てなり。用って祭祀するに利しとは、福を受くるなり。"], ["葛藟に臲卼に困しむ。曰く動けば悔ゆと。悔ゆる有りて往けば吉。", "葛藟に苦しむとは、未だ當らざるなり。動けば悔ゆと悔ゆる有るは、吉にして行くなり。"]], "ry": [["とん ちゅ ぼく くる ゆうこく い さんさい み", "ゆうこく い くら あきら"], ["しゅしょく くる しゅ ふつ まさ きた も きょう し よろ ゆ きょう とが な", "しゅしょく くる ちゅう よろこびあ"], ["いし くる しつ れい よ そのきゅう い そのつま み きょう", "しつれい よ ごう の そのきゅう い そのつま み ふしょう"], ["きた じょ じょ きん しゃ くる りん おわり あ", "きた じょ じょ こころざししも あ くらい あた いえど よ あ"], ["ぎ げつ せきふつ くる すなわ おもむ よろこびあ も さい し よろ", "ぎ げつ こころざしいま え すなわ おもむ よろこびあ ちゅうちょく もっ も さい し よろ さいわい う"], ["かつるい げきごつ くる いわ うご く く あ ゆ きつ", "かつるい くる いま あた うご く く あ きつ ゆ"]]}, "48": {"k": "井は、邑を改むれども井を改めず。喪ふ无く得る无し。往來、井を井とす。汔ど至らんとし、亦未だ井に繘せず、其瓶を羸るは、凶なり。", "rk": "せい ゆう あらた せい あらた うしな な う な おうらい せい せい ほとん いた またいま せい つるべなわ そのつるべ やぶ きょう", "t": "水に巽れて水を上ぐるは井なり。井は養ひて窮まらざるなり。邑を改むれども井を改めざるは、乃ち剛中なるを以てなり。汔ど至らんとし、亦、未だ井に繘せざるは、未だ功有らざるなり。其瓶を羸る。是を以て凶なり。", "rt": "みず い みず あ せい せい やしな きわ ゆう あらた せい あらた すなわ ごうちゅう もっ ほとん いた また いま せい つるべなわ いま こう あ そのつるべ やぶ ここ もっ きょう", "d": "木の上に水有るは、井なり。君子以て民に勞し相くるを勸む。", "rd": "き うえ みず あ せい くんし もっ たみ ろう たす すす", "y": [["井泥りて食はれず。舊井、禽无し。", "井泥りて食はれずとは、下なればなり。舊井、禽无しとは、時舍つるなり。"], ["井谷、鮒に射ぐ。甕敝れ漏る。", "井谷、鮒に射ぐとは、與无きなり。"], ["井渫へたれども食はれず。我が心の惻を爲す。用って汲む可し。王明かならば、竝に其福を受けん。", "井渫へたれども食はれず、行くゆく惻むなり。王の明かなるを求むるは、福を受くるなり。"], ["井甃す。咎无し。", "井甃す、咎无しとは、井を脩むるなり。"], ["井洌し。寒泉食はる。", "寒泉の食はるるは、中正なればなり。"], ["井收まる。幕ふ勿れ。孚有り。元吉。", "元吉にして上に在り。大いに成るなり。"]], "ry": [["せい にご くら きゅうせい とり な", "せい にご くら しも きゅうせい とり な とき す"], ["せいこく ふな そそ かめやぶ も", "せいこく ふな そそ くみするものな"], ["せいさら くら わ こころ いたみ な も く べ おうあきら とも そのふく う", "せいさら くら ゆ いた おう あきら もと ふく う"], ["せいいしだたみ とが な", "せいいしだたみ とが な せい おさ"], ["せいいさぎよ かん せん くら", "かんせん くら ちゅうせい"], ["せい く おお なか まこと あ げんきつ", "げんきつ うえ あ おお な"]]}, "49": {"k": "革は、己の日乃ち孚あり。元に亨る、貞しきに利し。悔亡ぶ。", "rk": "かく つちのと ひ すなわ まこと おおい とお ただ よろ くい ほろ", "t": "革は水火相息ぼし、二女同じく居り、其志、相得ざるを、革と曰ふ。己の日乃ち孚あり、革めて之を信ず。文明にして以て説び、大いに亨りて以て正し。革めて當り、其悔乃ち亡ぶ。天地革まりて四時成り、湯武、命を革め、天に順ひて人に應ず。革の時は大なるかな。", "rt": "かく すいか あいほろ にじょ おな お そのこころざし あいえ かく い つちのと ひ すなわ まこと あらた これ しん ぶんめい もっ よろこ おお とお もっ ただ あらた あた そのくいすなわ ほろ てんち あらた しいじ な とうぶ めい あらた てん したが ひと おう かく とき おおい", "d": "澤の中に火あるは革なり。君子以て歴を治め時を明かにす。", "rd": "たく なか ひ かく くんし もっ こよみ おさ とき あきら", "y": [["鞏むるに黄牛の革を用ふ。", "鞏むるに黄牛を用ふとは、以て爲す有る可からざるなり。"], ["己の日乃ち之を革む。征けば吉にして咎无し。", "己の日、之を革むとは、行きて嘉有るなり。"], ["征けば凶。貞しけれども厲し。革言三たび就る。孚有り。", "革言三たび就る。又何くにか之かん。"], ["悔亡ぶ。孚有り。命を改めて吉。", "命を改むるの吉は、志を信ずるなり。"], ["大人は虎變す。未だ占はずして孚有り。", "大人は虎變すとは、其文炳たるなり。"], ["君子は豹變す。小人は面を革む。征けば凶。貞に居れば吉。", "君子は豹變すとは、其文蔚たるなり。小人は面を革むとは、順にして以て君に從ふなり。"]], "ry": [["かた こうぎゅう かわ もち", "かた こうぎゅう もち もっ な あ べ"], ["つちのと ひ すなわ これ あらた ゆ きつ とが な", "つちのと ひ これ あらた ゆ よきこと あ"], ["ゆ きょう ただ あやう かくげん み な まこと あ", "かくげん み な またいず ゆ"], ["くい ほろ まこと あ めい あらた きつ", "めい あらた きつ こころざし しん"], ["たいじん こ へん いま うらな まこと あ", "たいじん こ へん その ぶんへい"], ["くんし ひょうへん しょうじん めん あらた ゆ きょう てい お きつ", "くんし ひょうへん そのぶんい（うつ） しょうじん めん あらた じゅん もっ きみ したが"]]}, "50": {"k": "鼎は元吉、亨る。", "rk": "てい げんきつ とお", "t": "鼎は象なり。木を以て火に巽れ、亨飪するなり。聖人、亨して以て上帝を享し、而して大いに亨して以て聖賢を養ふ。巽にして耳目總明、柔進みて上り行き、中を得て剛に應ず。是を以て元に亨る。", "rt": "てい しょう き もっ ひ い ほうじん せいじん ほう もっ じょうてい きょう しか おお ほう もっ せいけん やしな そん じ もく そう めい じゅうすす のぼ ゆ ちゅう え ごう おう ここ もっ おおい とお", "d": "木の上に火有るは鼎なり。君子以て位を正しくし命を凝す。", "rd": "き うえ ひ あ てい くんし もっ くらい ただ めい な", "y": [["鼎、趾を顚にす。否を出すに利し。妾を得て其子を以てす。咎无し。", "鼎、趾を顚にすとは、未だ悖らざるなり。否を出すに利しとは、以て貴に從ふなり。"], ["鼎、實有り。我が仇、疾有り。我に即く能はず。吉。", "鼎、實有りとは、之く所を愼むなり。我が仇、疾有りとは、終に尤无きなり。"], ["鼎の耳革まる。其行塞がる。雉の膏、食はれず。方に雨ふれば悔を虧く。終に吉。", "鼎の耳革まるとは、其義を失ふなり。"], ["鼎、足を折る。公の餗を覆す。其形渥たり。凶。", "公の餗を覆す。信に如何せんや。"], ["鼎黄耳にして、金鉉あり。貞しきに利し。", "鼎黄耳とは、中以て實と爲すなり。"], ["鼎、玉鉉あり。大吉にして、利しからざる无し。", "玉鉉、上に在るは、剛柔節するなり。"]], "ry": [["かなえ あし さかさま ひ いだ よろ しょう え その こ もっ とが な", "かなえ あし さかさま いま もと ひ いだ よろ もっ き したが"], ["かなえ じつ あ わ きゅう やまいあ われ つ あた きつ", "かなえ じつ あ ゆ ところ つつし わ きゅう やまいあ つい とが な"], ["かなえ みみあらた その こう ふさ きじ こう くら まさ あめ くい か つい きつ", "かなえ みみあらた その ぎ うしな"], ["かなえ あし お こう そく くつがえ そのかたちあく きょう", "こう そく くつがえ しん いかん"], ["かなえ こうじ きんげん ただ よろ", "かなえ こうじ ちゅうもっ じつ な"], ["かなえ ぎょくげん だいきつ よろ な", "ぎょくげん かみ あ ごうじゅうせっ"]]}, "51": {"k": "震は亨る。震の來るとき虩虩たり。笑言啞啞たり。震、百里を驚かせども、匕鬯を喪はず。", "rk": "しん とお しん きた げき げき しょうげん あくあく しん ひゃくり おどろ ひちょう うしな", "t": "震は亨る。震來るとき虩虩たりとは、恐れて福を致すなり。笑言啞啞たりとは、後に則有るなり。震、百里を驚かすとは、遠きを驚かして邇きを懼れしむるなり。出でては以て宗廟社稷を守り、以て祭主と爲る可きなり。", "rt": "しん とお しん きた げきげき おそ ふく いた しょうげん あくあく のち のり あ しん ひゃくり おどろ とお おどろ ちか おそ い もっ そうびょう しゃしょく まも もっ さいしゅ な べ", "d": "洊雷は震なり。君子以て恐懼し脩省す。", "rd": "せんらい しん くんし もっ きょうく しゅうせい", "y": [["震來るとき虩虩たり。後に笑言啞啞たり。吉。", "震來るとき虩虩たりとは、恐れて福を致すなり。笑言啞啞たりとは、後に則有るなり。"], ["震來るとき厲し。憶りて貝を喪ひ、九陵に躋る。逐ふ勿れ。七日にして得ん。", "震來るとき厲しとは、剛に乘ればなり。"], ["震して蘇蘇たり。震して行けば眚无し。", "震して蘇蘇たりとは、位、當らざるなり。"], ["震遂に泥む。", "震遂に泥むとは、未だ光ならざるなり。"], ["震して往くも來るも厲し。億りて事有るを喪ふ无し。", "震して往くも來るも厲しとは、危行なり。其事、中に在り、大いに喪ふ无きなり。"], ["震して索索たり。視ること矍矍たり。征けば凶。震、其躬に于てせず、其隣に于てすれば、咎无し。婚媾、言有り。", "震して索索たりとは、中未だ得ざるなり。凶なりと雖も咎无しとは、隣を畏れて戒むるなり。"]], "ry": [["しん きた げきげき のち しょうげん あくあく きつ", "しん きた げきげき おそ ふく いた しょうげん あくあく のち のり あ"], ["しんきた あやう おもんぱか ばい うしな きゅうりょう のぼ お なか なぬか え", "しんきた あやう ごう の"], ["しん そ そ しん ゆ あやまちな", "しん そ そ くらい あた"], ["しんつい なず", "しんつい なず いま おおい"], ["しん ゆ きた あやう おもんぱか こと あ うしな な", "しん ゆ きた あやう き こう そのこと ちゅう あ おお うしな な"], ["しん さく さく み かく かく ゆ きょう しん その み おい そのとなり おい とが な こん こう げん あ", "しん さく さく うち いま え きょう いえど とが な となり おそ いまし"]]}, "52": {"k": "其背に艮まり、其身を獲ず。其庭に行き、其人を見ず。咎无し。", "rk": "そのせ とど そのみ え そのにわ ゆ そのひと み とがな", "t": "艮は止まるなり。時止まれば則ち止まり、時行けば則ち行き、動静、其時を失わず、其道光明なり。其止に艮まるは、其所に止まるなり。上下敵應し、相與せざるなり。是を以て、其身を獲ず、其庭に行き、其人を見ず、咎无きなり。", "rt": "ごん とど ときとど すなわ とど とき ゆ すなわ ゆ どうせい そのとき うしな そのみち こうめい その し とど そのところ とど じょうげ てきおう あいくみ ここ もっ その み え そのにわ ゆ そのひと み とが な", "d": "兼山は艮なり。君子以て思ふこと其位を出でず。", "rd": "けんさん ごん くんし もっ おも そのくらい い", "y": [["其趾に艮まる。咎无し。永貞に利し。", "其趾に艮まるとは、未だ正を失はざるなり。"], ["其腓に艮まる。其の隨を拯はず。其心、快からず。", "其隨を拯はずとは、未だ退き聴かざるなり。"], ["其限に艮まる。其夤を列く。厲くして心を薫す。", "其限に艮まるとは、危うくして心を薫するなり。"], ["其身に艮まる。咎无し。", "其身に艮まるとは、諸を躬に止むるなり。"], ["其輔に艮まる。言、序有り。悔亡ぶ。", "其輔に艮まるとは、中正を以てなり。"], ["艮まるに敦し。吉。", "艮まるに敦きの吉は、終を厚くするを以てなり。"]], "ry": [["そのあし とど とが な えいてい よろ", "そのあし とど いま せい うしな"], ["その ひ とど そ ずい すく そのこころ こころよ", "そのずい すく いま しりぞ き"], ["そのげん とど そのいん さ あやう こころ くん", "そのげん とど あや こころ くん"], ["その み とど とが な", "その み とど これ み とど"], ["その ほ とど げん じょ あ くい ほろ", "その ほ とど ちゅうせい もっ"], ["とど あつ きつ", "とど あつ きつ おわり あつ もっ"]]}, "53": {"k": "漸は、女歸ぎて吉。貞しきに利し。", "rk": "ぜん じょ とつ きつ ただ よろ", "t": "漸は之き進むなり。女歸ぎて吉なるなり。進みて位を得、往きて功有るなり。進むに正しきを以てす、以て邦を正す可きなり。其位、剛、中を得るなり。止まりて巽、動きて窮まらざるなり。", "rt": "ぜん ゆ すす じょとつ きつ すす くらい え ゆ こう あ すす ただ もっ もっ くに ただ べ そのくらい ごう ちゅう う とど そん うご きわ", "d": "山の上に木有るは漸なり。君子以て賢徳に居り俗を善くす。", "rd": "やま うえ き あ ぜん くんし もっ けんとく お ぞく よ", "y": [["鴻、干に漸む。小子は厲し。言有れども咎无し。", "小子の厲きは、義、咎无きなり。"], ["鴻、磐に漸む。飲食衎衎たり。吉。", "飲食衎衎たりとは、素飽せざるなり。"], ["鴻、陸に漸む。夫征きて復らず、婦孕みて育せず。凶。寇を禦ぐに利し。", "夫征きて復らずとは、群醜を離るるなり。婦孕みて育せずとは、其道を失ふなり。用って寇を禦ぐに利しとは、順にして相保つなり。"], ["鴻木に漸む。或は其桷を得れば、咎无し。", "或は其桷を得とは、順にして以て巽なるなり。"], ["鴻、陵に漸む。婦、三歳まで孕まず。終に之に勝つ莫し。吉。", "終に之に莫し、吉とは、願ふ所を得るなり。"], ["鴻、逵に漸む。其羽は用って儀と爲す可し。吉。", "其羽は用って儀と爲す可し、吉とは、亂る可からざるなり。"]], "ry": [["こう みぎわ すす しょうし あやう げん あ とがな", "しょうし あやう ぎ とが な"], ["こう おおいし すす いんしょく かんかん きつ", "いんしょく かんかん そ ほう"], ["こう くが すす おっと ゆ かえ つまはら いく きょう あだ ふせ よろ", "おっとゆ かえ ぐんしゅう はな つまはら いく そのみち うしな も あだ ふせ よろ じゅん あいたも"], ["こう き すす あるい そのかく う とが な", "あるい その かく う じゅん もっ そん"], ["こう おか すす つま さんさい はら つい これ か な きつ", "つい これ な きつ ねが ところ う"], ["こう おか すす そのはね も ぎ な べ きつ", "そのはね も ぎ な べ きつ みだ べ"]]}, "54": {"k": "帰妹は、征けば凶。利しき攸无し。", "rk": "き まい ゆ きょう よろ ところ な", "t": "歸妹は、天地の大義なり。天地、交はらざれば萬物、興らず。歸妹は人の終始なり。説びて以て動く、歸ぐ所は妹なり。征けば凶なるは、位、當らざればなり。利しき攸无きは、柔、剛に乘ずればなり。", "rt": "き まい てん ち たいぎ てんち まじ ばんぶつ おこ きまい ひと しゅうし よろこ もっ うご とつ ところ まい ゆ きょう くらい あた よろ ところ な じゅう ごう じょう", "d": "澤の上に雷有るは歸妹なり。君子以て終りを永くし敝を知る。", "rd": "たく うえ らい あ きまい くんし もっ おわ なが へい し", "y": [["妹を歸がするに娣を以てす。跛能く履む。征きて吉。", "妹を歸がするに娣を以てすとは、以て恒あるなり。跛能く履む。吉とは、相承くるなり。"], ["眇にして能く視る。幽人の貞に利し。", "幽人の貞に利しとは、未だ常を變ぜざるなり。"], ["妹を歸がするに以て須つ。反れば歸ぐに娣を以てす。", "妹を歸がするに以て須つとは、未だ當らざるなり。"], ["妹を歸がするに期を愆ぐ。歸ぐを遲つこと時有り。", "期を愆ぐるの志は、待つ有りて行くなり。"], ["帝乙、妹を歸がす。其君の袂は、其娣の袂の良きに如かず。月、望に幾し。吉。", "帝乙、妹を歸がす、其娣の袂の良きに如かざるなり。其位、中に在り、貴を以て行くなり。"], ["女、筐を承けて實无く、士、羊を刲きて血无し。利しき攸无し。", "上六、實无きは、虚筐を承くるなり。"]], "ry": [["まい とつ てい もっ あしなえよ ふ ゆ きつ", "まい とつ てい もっ もっ つね あしなえよ ふ きつ あい う"], ["びょう よ み ゆうじん てい よろ", "ゆうじん てい よろ いま つね へん"], ["まい とつ もっ ま かえ とつ てい もっ", "まい とつ もっ ま いま あた"], ["まい とつ き す とつ ま とき あ", "き す こころざし ま あ ゆ"], ["ていいつ まい とつ そのきみ たもと そのてい たもと よ し つき ぼう ちか きつ", "てい いつ まい とつ そのてい たもと よ し そのくらい ちゅう あ き もっ ゆ"], ["じょ かたみ う み な し ひつじ さ ち な よろ ところ な", "じょうりく み な きょかたみ う"]]}, "55": {"k": "豐は亨る。王、之に假る。憂ふる勿れ。日中に宜し。", "rk": "ほう とお おう これ いた うれ なか ひちゅう よろ", "t": "豐は大なるなり。明かにして以て動く、故に豐なり。王、之に假るとは、大を尚ぶなり。憂ふる勿れ、日中に宜しとは、宜しく天下を照らすべきなり。日中すれば則ち昃く。月盈つれば則ち食く。天地の盈虚は、時と與に消息す。而るを況んや人に于てをや。況んや鬼神に于てをや。", "rt": "ほう だい あきら もっ うご ゆえ ほう おう これ いた だい たつと うれ なか ひちゅう よろ よろ てんか て ひちゅう すなわ かたむ つき み すなわ か てんち えいきょ とき とも しょうそく しか いわ ひと おい いわ きしん おい", "d": "雷電皆至るは豐なり。君子以て獄を折ち刑を致す。", "rd": "らい でん みな いた ほう くんし もっ ごく わか けい いた", "y": [["其配主に遇ふ。旬しと雖も咎无し。往きて尚ばるる有り。", "旬しと雖も咎无しとは、旬しきを過ぐれば災なり。"], ["其蔀を豐にす。日中に斗を見る。往きて疑疾を得。孚有り發若すれば、吉。", "孚有り發若すとは、信以て志を發するなり。"], ["其沛を豐にす。日中に沬を見る。其右肱を折る。咎无し。", "其沛を豐にすとは、大事に可ならざるなり。其右肱を折るとは、終に用ふ可からざるなり。"], ["其蔀を豐にす。日中に斗を見る。其夷主に遇へば、吉。", "其蔀を豐にすとは、位、當らざるなり。日中に斗を見るとは、幽くして明かならざるなり。其夷主に遇ふとは、吉の行なり。"], ["章を來す、慶譽有り。吉。", "六五の吉は、慶有るなり。"], ["其屋を豐にす。其家を蔀ふ。其戸を闚ふに、闃として其れ人无し。三歳まで觀ず。凶。", "其屋を豐にすとは、天際に翔るなり。其戸を闚ふに、闃として其れ人无しとは、自ら藏るるなり。"]], "ry": [["そのはいしゅ あ ひと いえど とが な ゆ たつと あ", "ひと いえど とが な ひと す わざわい"], ["そのほう おおい ひちゅう と み ゆ ぎしつ う まこと あ はつじゃく きつ", "まこと あ はつじゃく しん もっ こころざし はっ"], ["そのはい おおい にっちゅう ばい み その う こう お とが な", "そのはい おおい だいじ か その う こう お つい もち べ"], ["そのほう おおい にっちゅう と み その い しゅ あ きつ", "その ほう おおい くらい あた にっちゅう と み くら あきら その い しゅ あ きつ こう"], ["しょう きた けい よ あ きつ", "りくご きつ よろこびあ"], ["そのおく おおい その いえ おお その こ うかが げき そ ひと な さんさい み きょう", "その おく おおい てんさい かけ その こ うかが げき そ ひと な みずか かく"]]}, "56": {"k": "旅は小しく亨る。旅は貞にして吉。", "rk": "りょ すこ とお りょ てい きつ", "t": "旅は小しく亨る。柔、中を外に得て、剛に順ひ、止まりて明に麗く。是を以て小しく亨る。旅は貞にして吉なり。旅の時義大いなるかな。", "rt": "りょ すこ とお じゅう ちゅう そと え ごう したが とど めい つ ここ もっ すこ とお りょ てい きつ りょ とき ぎ おおい", "d": "山の上に火有るは旅なり。君子以て明かに愼みて刑を用ひ、而して獄を留めず。", "rd": "やま うえ ひ あ りょ くんし もっ あきら つつし けい もち しか ごく とど", "y": [["旅にして瑣瑣たり。斯れ其の災を取る所なり。", "旅して瑣瑣たりとは、志窮まるの災なり。"], ["旅にして次に即く。其資を懐く。童僕の貞を得。", "童僕の貞を得とは、終に尤むる無きなり。"], ["旅して其次を焚く。其童僕の貞を喪ふ。厲し。", "旅にして其次を焚く。亦以に傷まし。旅を以て下に與する、其義喪ふなり。"], ["旅して于に處る。其資斧を得。我が心、快からず。", "旅して于に處るとは、未だ位を得ざるなり。其資斧を得とは、心未だ快からざるなり。"], ["雉を射て一矢亡ふ。終に以て譽命あり。", "終に以て譽命ありとは、上逮ぶなり。"], ["鳥、其巣を焚く。旅人先には笑ひ、後には號咷す。牛を易に喪ふ。凶。", "旅を以て上に在り、其義焚かるるなり。牛を易に喪ふ、終に之を聞く莫きなり。"]], "ry": [["りょ さ さ こ そ わざわい と ところ", "りょ さ さ こころざしきわ わざわい"], ["りょ やどり つ その し いだ どうぼく てい う", "どうぼく てい う つい とが な"], ["りょ そのやどり や その どうぼく てい うしな あやう", "りょ そのやどり や またすで いた りょ もっ しも くみ その ぎ うしな"], ["りょ ここ お その し ふ う わ こころ こころよ", "りょ ここ お いま くらい え その し ふ う こころいま こころよ"], ["きじ い いっし うしな つい もっ よめい", "つい もっ よめい かみおよ"], ["とり その す や りょじん さき わら のち ごうとう うし えき うしな きょう", "りょ もっ かみ あ その ぎ や うし えき うしな つい これ き な"]]}, "57": {"k": "巽は小しく亨る。往く攸有るに利し。大人を見るに利し。", "rk": "そん すこ とお ゆ ところ あ よろ たいじん み よろ", "t": "重巽にして以て命を申ぬ。剛、中正に巽ひて志行はる。柔、皆、剛に順ふ。是を以て小しく亨り、往く攸有るに利しく、大人を見るに利し。", "rt": "ちょうそん もっ めい かさ ごう ちゅうせい したが こころざしおこな じゅう みな ごう したが ここ もっ すこ とお ゆ ところ あ よろ たいじん み よろ", "d": "隨風は巽なり。君子以て命を申ね事を行ふ。", "rd": "ずいふう そん くんし もっ めい かさ こと おこな", "y": [["進退す。武人の貞に利し。", "進退すとは、志疑ふなり。武人の貞に利しとは、志治まるなり。"], ["巽して牀下に在り。史巫を用ふること紛若たり。吉にして咎无し。", "紛若たるの吉は、中を得ればなり。"], ["頻に巽す。吝。", "頻に巽するの吝は、志窮まるなり。"], ["悔亡ぶ。田して三品を獲。", "田して三品を獲とは、功有るなり。"], ["貞にして吉、悔亡ぶ。利しからざる无し。初无く終有り。庚に先だつこと三日、庚に後るること三日。吉。", "九五の吉は、位正中なればなり。"], ["巽して牀下に在り。其資斧を喪ふ。貞なれども凶。", "巽して牀下に在りとは、上にして窮まるなり。其資斧を喪ふとは、正乎として凶なるなり。"]], "ry": [["しんたい ぶじん てい よろ", "しんたい こころざしうたが ぶじん てい よろ こころざしおさ"], ["そん しょうか あ し ふ もち ふんじゃく きつ とが な", "ふんじゃく きつ ちゅう う"], ["しきり そん りん", "しきり そん りん こころざしきわ"], ["くい ほろ でん さんぴん う", "でん さんぴん う こう あ"], ["てい きつ くい ほろ よろ な はじめな おわりあ こう さき みっか こう おく みっか きつ", "きゅうご きつ くらいせいちゅう"], ["そん しょうか あ その し ふ うしな てい きょう", "そん しょうか あ かみ きわ その し ふ うしな せい こ きょう"]]}, "58": {"k": "兌は亨る。貞しきに利し。", "rk": "だ とお ただ よろ", "t": "兌は説ぶなり。剛は中にして柔は外なり。説びて以て貞しきに利し。是を以て天に順ひて人に應ず。説びて以て民に先だてば、民、其勞を忘る。説びて以て難を犯せば、民、其死を忘る。説びの大なる、民勸むかな。", "rt": "だ よろこ ごう ちゅう じゅう そと よろこ もっ ただ よろ ここ もっ てん したが ひと おう よろこ もっ たみ さき たみ そのろう わす よろこ もっ なん おか たみ その し わす よろこ だい たみつと", "d": "麗澤は兌なり。君子以て朋友講習す。", "rd": "れいたく だ くんし もっ ほうゆう こうしゅう", "y": [["和ぎて兌ぶ。吉。", "和ぎて兌ぶの吉は、行未だ疑はざるなり。"], ["孚ありて兌ぶ。吉。悔亡ぶ。", "孚ありて兌ぶの吉は、志を信ずるなり。"], ["來りて兌ぶ。凶。", "來りて兌ぶの凶は、位、當らざるなり。"], ["商りて兌び、未だ寧んぜず。疾を介つれば喜有り。", "九四の喜は、慶有るなり。"], ["剝に孚あり。厲き有り。", "剝に孚ありとは、位正しく當ればなり。"], ["引きて兌ぶ。", "上六の引きて兌ぶは、未だ光ならざるなり。"]], "ry": [["やわら よろこ きつ", "やわら よろこ きつ おこないいま うたが"], ["まこと よろこ きつ くいほろ", "まこと よろこ きつ こころざし しん"], ["きた よろこ きょう", "きた よろこ きょう くらい あた"], ["はか よろこ いま やす しつ へだ よろこびあ", "きゅうし よろこび よろこびあ"], ["はく まこと あやう あ", "はく まこと くらいただ あた"], ["ひ よろこ", "じょうりく ひ よろこ いま おおい"]]}, "59": {"k": "渙は亨る。王、有廟に假る。大川を渉るに利し。貞しきに利し。", "rk": "かん とお おう ゆうびょう いた たいせん わた よろ ただ よろ", "t": "渙は亨るとは、剛來りて窮まらず、柔、位を外に得て上同すればなり。王、有廟に假るとは、王乃ち中に在るなり。大川を渉るに利しとは、木に乘りて功有るなり。", "rt": "かん とお ごう きた きわ じゅう くらい そと え じょうどう おう ゆうびょう いた おうすなわ ちゅう あ たいせん わた よろ き の こう あ", "d": "風、水の上を行くは、渙なり。先王以て帝に享し、廟を立つ。", "rd": "かぜ みず うえ ゆ かん せんおう もっ てい きょう びょう た", "y": [["用って拯ふに馬壯んなり。吉。", "初六の吉は、順なればなり。"], ["渙のとき其机に奔る。悔亡ぶ。", "渙のとき其机に奔るは、願を得るなり。"], ["其躬を渙す。悔无し。", "其躬を渙すとは、志、外に在るなり。"], ["其羣を渙す。元吉。渙のとき丘有り。夷の思う所に匪ず。", "其羣を渙す、元吉とは、光大なるなり。"], ["渙のとき其大號を汗にす。渙のとき王居る。咎无し。", "王居り、咎无しとは、位を正しくするなり。"], ["其血を渙す。去りて逖く出づ。咎无し。", "其血を渙すとは、害に遠ざかるなり。"]], "ry": [["も すく うま さか きつ", "しょりく きつ じゅん"], ["かん その き はし くいほろ", "かん その き はし ねがい う"], ["その み ちら くい な", "その み ちら こころざし ほか あ"], ["そのぐん ちら げんきつ かん きゅうあ つね おも ところ あら", "そのぐん ちら げんきつ ひかりおおい"], ["かん その たい ごう あせ かん おう お とが な", "おう お とが な くらい ただ"], ["その ち ちら さ とお い とが な", "その ち ちら がい とお"]]}, "60": {"k": "節は亨る。苦節は貞にす可からず。", "rk": "せつ とお くせつ てい べ", "t": "節は亨るとは、剛柔分れて、剛、中を得ればなり。苦節は貞にす可からずとは、其道窮まるなり。説びて以て險を行ひ、位に當りて以て節し、中正にして以て通ず。天地節して四時成る。節以て度を制し、財を傷はず、民を害はず。", "rt": "せつ とお ごうじゅうわか ごう ちゅう う くせつ てい べ そのみち きわ よろこ もっ けん おこな くらい あた もっ せっ ちゅうせい もっ つう てんち せっ しいじ な せつ もっ ど せい ざい そこな たみ そこな", "d": "澤の上に水有るは、節なり。君子以て數度を制し德行を議す。", "rd": "たく うえ みず あ せつ くんし もっ すう ど せい とく こう ぎ", "y": [["戸庭を出でず。咎无し。", "戸庭を出でずとは、通塞を知るなり。"], ["門庭を出でず。凶。", "門庭を出でず、凶とは、時を失ふこと極まれるなり。"], ["節若せざれば、則ち嗟若す。咎无し。", "節せざるの嗟は、又誰か咎めんや。"], ["節に安んず。亨る。", "節に安んずるの亨るは、上の道を承くるなり。"], ["甘節なり。吉。往きて尚ばるる有り。", "甘節の吉は、位に居ること中なるなり。"], ["苦節なり。貞なるも凶。悔亡ぶ。", "苦節なり、貞なるも凶とは、其道窮まるなり。"]], "ry": [["こてい い とが な", "こ てい い つうそく し"], ["もんてい い きょう", "もんてい い きょう とき うしな"], ["せつじゃく すなわ さじゃく とが な", "せっ なげき まただれ とが"], ["せつ やす とお", "せつ やす とお かみ みち う"], ["かんせつ きつ ゆ たつと あ", "かんせつ きつ くらい お ちゅう"], ["く せつ てい きょう くい ほろ", "く せつ てい きょう そのみち きわ"]]}, "61": {"k": "中孚は、豚魚吉。大川を渉るに利し。貞しきに利し。", "rk": "ちゅう ふ とんぎょ きつ たいせん わた よろ ただ よろ", "t": "中孚は、柔、内に在りて、剛、中を得、説びて巽ひ、孚あり、乃ち邦を化するなり。豚魚吉とは、信、豚魚に及ぶなり。大川を渉るに利しとは、木に乘りて舟虚なるなり。中孚にして以て貞しきに利しとは、乃ち天に應ずるなり。", "rt": "ちゅう ふ じゅう うち あ ごう ちゅう え よろこ したが まこと すなわ ほう か とんぎょ きつ しん とんぎょ およ たいせん わた よろ き の ふねきょ ちゅうふ もっ ただ よろ すなわ てん おう", "d": "澤の上に風有るは、中孚なり。君子以て獄を議し死を緩かにす。", "rd": "たく うえ かぜ あ ちゅうふ くんし もっ ごく ぎ し ゆるや", "y": [["虞れば吉。他有れば燕からず。", "初九虞れば吉とは、志未だ變ぜざるなり。"], ["鳴鶴、陰に在り。其子、之に和す。我、好爵有り、吾、爾と之を靡にせん。", "其子、之に和すとは、中心願ふなり。"], ["敵を得、或は鼓し或は罷め、或は泣き或は歌ふ。", "或は鼓し或は罷むるは、位、當らざるなり。"], ["月、望に幾し。馬匹亡ぶ。咎无し。", "馬匹亡ぶとは、類を絶ちて上るなり。"], ["孚有り攣如たり。咎无し。", "孚有り攣如たりとは、位、正に當るなり。"], ["翰音、天に登る。貞なるも凶。", "翰音、天に登る、何ぞ長かる可けんや。"]], "ry": [["おもんぱか きつ た あ やす", "しょきゅうおもんぱかれ きつ こころざしいま へん"], ["めいかく いん あ その こ これ わ われ こうしゃく あ われ なんじ これ とも", "その こ これ わ ちゅうしんねが"], ["てき え あるい こ あるい や あるい な あるい うた", "あるい こ あるい や くらい あた"], ["つき ぼう ちか ば ひつ ほろ とが な", "ば ひつ ほろ るい た のぼ"], ["まこと あ れんじょ とが な", "まこと あ れんじょ くらい まさ あた"], ["かんおん てん のぼ てい きょう", "かんおん てん のぼ なん なが べ"]]}, "62": {"k": "小過は、亨る。貞しきに利し。小事に可なり、大事に可ならず。飛鳥、之が音を遺す。上るに宜しからず、下るに宜し。大吉。", "rk": "しょうか とお ただ よろ しょうじ か だいじ か ひちょう これ ね のこ のぼ よろ くだ よろ だいきつ", "t": "小過は、小なる者過ぎて亨るなり。過ぎて以て貞しきに利しとは、時と與に行ふなり。柔、中を得。是を以て小事は吉なるなり。剛、位を失ひて中ならず。是を以て大事に可ならざるなり。飛鳥の象有り。飛鳥、之が音を遺す、上るに宜しからず、下るに宜し、大吉とは、上るは逆にして下るは順なればなり。", "rt": "しょうか しょう もの す とお す もっ ただ よろ とき とも おこな じゅう ちゅう う ここ もっ しょうじ きつ ごう くらい うしな ちゅう ここ もっ だいじ か ひちょう しょう あ ひちょう これ ね のこ のぼ よろ くだ よろ だいきつ のぼ ぎゃく くだ じゅん", "d": "山の上に雷有るは、小過なり。君子以て行は恭しきに過ぎ、喪は哀しみに過ぎ、用は儉に過ぐ。", "rd": "やま うえ らい あ しょう か くんし もっ おこない うやうや す も かな す よう けん す", "y": [["飛鳥、以て凶。", "飛鳥、以て凶とは、如何ともす可からざるなり。"], ["其祖を過ぎ、其妣に遇ふ。其君に及ばず、其臣に遇ふ。咎无し。", "其君に及ばず、臣は過ぐ可からざるなり。"], ["過ぎず、之を防ぐ。從って或は之を戕はば、凶。", "從って或は之を戕はば、凶如何せんや。"], ["咎无し。過ぎず、之に遇ふ。往けば厲し。必ず戒めよ。用ふる勿れ。永く貞なれ。", "過ぎず之に遇ふとは、位、當らざるなり。往けば厲し、必ず戒めよとは、終に長かる可からざるなり。"], ["密雲、雨ふらず、我が西郊よりす。公、弋して彼の穴に在るを取る。", "密雲、雨ふらずとは已だ上ればなり。"], ["遇はず、之を過ぐ。飛鳥、之に離る。凶。是れを災眚と謂ふ。", "遇はず之を過ぐとは、已だ亢るなり。"]], "ry": [["ひちょう もっ きょう", "ひちょう もっ きょう いかん べ"], ["そのそ す その ひ あ そのきみ およ そのしん あ とが な", "その きみ およ しん す べ"], ["す これ ふせ したが あるい これ そこな きょう", "したが あるい これ そこな きょう いかん"], ["とが な す これ あ ゆ あやう かなら いまし もち なか なが てい", "す これ あ くらい あた ゆ あやう かなら いまし つい なが べ"], ["みつうん あめ わ せいこう こう よく か あな あ と", "みつうん あめ はなは のぼ"], ["あ これ す ひちょう これ かか きょう こ さいせい い", "あ これ す はなは たかぶ"]]}, "63": {"k": "既濟は、亨ること小なり。貞しきに利し。初めは吉、終りは亂る。", "rk": "きせい とお しょう ただ よろ はじ きつ おわ みだ", "t": "既濟は亨るとは、小なる者亨るなり。貞しきに利しとは、剛柔正しくして位當ればなり。初めは吉とは、柔、中を得ればなり。終りに止まれば則ち亂る、其道窮まるなり。", "rt": "き せい とお しょう もの とお ただ よろ ごうじゅう ただ くらいあた はじ きつ じゅう ちゅう う おわ とど すなわ みだ そのみち きわ", "d": "水、火の上に在るは、既濟なり。君子以て患を思うて預め之を防ぐ。", "rd": "みず ひ うえ あ き せい くんし もっ うれい おも あらかじ これ ふせ", "y": [["其輪を曳く。其尾を濡らす。咎无し。", "其輪を曳くとは、義、咎无きなり。"], ["婦、其茀を喪ふ。逐ふ勿れ。七日にして得ん。", "七日にして得とは、中道を以てなり。"], ["高宗、鬼方を伐つ。三年にして之に克つ。小人は用ふる勿れ。", "三年にして之に克つとは、憊るるなり。"], ["繻るるに衣袽有り。（繻に衣袽有り）終日戒む。", "終日戒むとは、疑ふ所有るなり。"], ["東鄰に牛を殺すは、西鄰の禴祭して、實に其福を受くるに如かず。", "東鄰に牛を殺すは、西鄰の時なるに如かざるなり。實に其福を受くとは、吉大いに來るなり。"], ["其首を濡らす。厲し。", "其首を濡らす、厲しとは、何ぞ久しかる可けんや。"]], "ry": [["その わ ひ その お ぬ とが な", "その わ ひ ぎ とが な"], ["ふ そのふつ うしな お なか なぬか え", "なぬか う ちゅうどう もっ"], ["こうそう き ほう う さんねん これ か しょうじん もち なか", "さんねん これ か つか"], ["ぬ い じょ あ じゅ い じょ あ しゅうじついまし", "しゅうじついまし うたが ところ あ"], ["とうりん うし ころ せいりん やく さい じつ そのさいわい う し", "とう りん うし ころ せい りん とき し じつ そのさいわい う きつおおい きた"], ["そのこうべ ぬ あやう", "そのこうべ ぬ あやう なん ひさ べ"]]}, "64": {"k": "未濟は亨る。小狐汔ど濟らんとし、其尾を濡らす。利しき攸无し。", "rk": "びせい とお しょう こ ほとん わた その お ぬ よろ ところ な", "t": "未濟は亨るは、柔、中を得ればなり。小狐汔ど濟らんとすとは、未だ中を出でざるなり。其尾を濡らす、利しき攸无しとは、續きて終らざるなり。位に當らずと雖も、剛柔應ずるなり。", "rt": "び せい とお じゅう ちゅう う しょうこ ほとん わた いま なか い その お ぬ よろ ところ な つづ おわ くらい あた いえど ごうじゅう おう", "d": "火、水の上に在るは未濟なり。君子以て愼みて物を辯じ方に居く。", "rd": "ひ みず うえ あ び せい くんし もっ つつし もの べん ほう お", "y": [["其尾を濡らす。吝。", "其尾を濡らすとは、亦、極を知らざるなり。"], ["其輪を曳く。貞にして吉。", "九二の貞にして吉とは、中以て正を行ふなり。"], ["未だ濟らず。征くは凶。大川を渉るに利し。", "未だ濟らず、征くは凶とは、位、當らざるなり。"], ["貞にして吉。悔亡ぶ。震して用って鬼方を伐つ。三年にして大國に賞有り。", "貞にして吉、悔亡ぶとは、志行はるるなり。"], ["貞にして吉、悔无し。君子の光なり。孚有り、吉。", "君子の光とは、其れ暉きて吉なるなり。"], ["酒を飲むに孚有り。（孚有り于に酒を飲む）咎无し。其首を濡らせば、孚有れども是を失ふ。", "酒を飲み首を濡らすは、亦節を知らざるなり。"]], "ry": [["その お ぬ りん", "その お ぬ また きょく し"], ["その わ ひ てい きつ", "きゅうじ てい きつ ちゅうもっ せい おこな"], ["いま わた ゆ きょう たいせん わた よろ", "いま わた ゆ きょう くらい あた"], ["てい きつ くいほろ しん も き ほう う さんねん たいこく しょう あ", "てい きつ くいほろ こころざしおこな"], ["てい きつ くい な くんし ひかり まこと あ きつ", "くんし ひかり そ かがや きつ"], ["さけ の まこと あ まこと あ ここ さけ の とが な そのこうべ ぬ まこと あ ぜ うしな", "さけ の こうべ ぬ また せつ し"]]}};TK.kd=TK.kd||{};for(var n in X)TK.kd[n]=X[n];})();
